# ==================== MODULE 1: TỰ ĐỘNG CẤU HÌNH THƯ VIỆN & FFMPEG ====================
def ensure_packages():
    try:
        from PIL import Image, ImageDraw
    except ImportError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "Pillow"])

    if shutil.which("ffmpeg") and shutil.which("ffprobe"):
        return

    if os.name == "nt":
        winget_dir = os.path.expandvars(r"%LOCALAPPDATA%\Microsoft\WinGet\Packages")
        if os.path.exists(winget_dir):
            for root, _, files in os.walk(winget_dir):
                if "ffmpeg.exe" in files:
                    os.environ["PATH"] = root + os.pathsep + os.environ.get("PATH", "")
                    if shutil.which("ffmpeg"):
                        return

    try:
        import static_ffmpeg
        static_ffmpeg.add_paths()
    except ImportError:
        print("[*] Đang tự động cài đặt gói 'static-ffmpeg'...")
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "static-ffmpeg"])
        import static_ffmpeg
        static_ffmpeg.add_paths()

ensure_packages()
from PIL import Image, ImageDraw
