# ==================== HỆ THỐNG LỊCH SỬ VIDEO ĐÃ LÀM & TỰ ĐỘNG DỌN DẸP 5-7 NGÀY ====================
HISTORY_RETENTION_DAYS = 7 # Tự động xóa lịch sử và giải phóng video sau 7 ngày (phù hợp GoFile)

def get_workspace_history_path(ws_id):
    ws_dir = os.path.join(WORKSPACES_ROOT, f"ws_{ws_id}")
    os.makedirs(ws_dir, exist_ok=True)
    return os.path.join(ws_dir, "history.json")

def load_workspace_history(ws_id):
    path = get_workspace_history_path(ws_id)
    if os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    return []

def save_workspace_history(ws_id, items):
    path = get_workspace_history_path(ws_id)
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(items, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[!] Lỗi lưu history ws_{ws_id}: {e}", flush=True)

def cleanup_expired_history(target_ws_id=None, max_days=7):
    """
    Tự động quét và dọn dẹp các video & lịch sử đã quá hạn (5-7 ngày)
    để giải phóng dung lượng đĩa Railway và đồng bộ thời hạn lưu trữ GoFile.
    """
    now_dt = datetime.now()
    ws_ids = [target_ws_id] if target_ws_id else []
    if not ws_ids:
        if os.path.exists(WORKSPACES_ROOT):
            for d in os.listdir(WORKSPACES_ROOT):
                if d.startswith("ws_"):
                    ws_ids.append(d[3:])
    
    for wid in ws_ids:
        hpath = get_workspace_history_path(wid)
        if not os.path.exists(hpath):
            continue
        try:
            items = load_workspace_history(wid)
            kept_items = []
            changed = False
            for it in items:
                exp_str = it.get("expires_at")
                c_str = it.get("created_at")
                is_expired = False
                if exp_str:
                    try:
                        if now_dt > datetime.fromisoformat(exp_str):
                            is_expired = True
                    except Exception:
                        pass
                elif c_str:
                    try:
                        c_dt = datetime.fromisoformat(c_str)
                        if (now_dt - c_dt).days >= max_days:
                            is_expired = True
                    except Exception:
                        pass
                
                if is_expired:
                    changed = True
                    # Xóa file vật lý tương ứng nếu tồn tại để giải phóng ổ cứng
                    fpath = it.get("file_path")
                    if fpath and os.path.exists(fpath):
                        try: os.remove(fpath)
                        except Exception: pass
                else:
                    kept_items.append(it)
            
            if changed:
                save_workspace_history(wid, kept_items)
        except Exception as e:
            print(f"[!] Lỗi cleanup history ws_{wid}: {e}", flush=True)

def record_video_history(ws_id, item):
    """
    Ghi nhận một video đã hoàn tất vào lịch sử của workspace:
    """
    if not ws_id:
        ws_id = "default"
    items = load_workspace_history(ws_id)
    hist_id = item.get("id") or f"hist_{int(time.time())}_{hashlib.md5(str(time.time()).encode()).hexdigest()[:6]}"
    now_dt = datetime.now()
    exp_dt = now_dt + timedelta(days=HISTORY_RETENTION_DAYS)
    
    fname = item.get("filename") or "output_vietsub.mp4"
    record = {
        "id": hist_id,
        "title": item.get("title") or fname or "Video Vietsub",
        "filename": fname,
        "file_path": item.get("file_path", ""),
        "file_size_mb": round(float(item.get("file_size_mb") or 0.0), 2),
        "duration_sec": round(float(item.get("duration_sec") or 0.0), 1),
        "gofile_url": item.get("gofile_url") or "",
        "download_url": f"/api/workspace/video/download?file={fname}&ws={ws_id}",
        "preview_url": f"/api/workspace/video/stream?file={fname}&ws={ws_id}",
        "created_at": item.get("created_at") or now_dt.isoformat(),
        "expires_at": item.get("expires_at") or exp_dt.isoformat(),
        "status": "completed"
    }
    items = [x for x in items if x.get("id") != hist_id]
    items.insert(0, record)
    save_workspace_history(ws_id, items)
    try:
        cleanup_expired_history(ws_id, max_days=HISTORY_RETENTION_DAYS)
    except Exception:
        pass
    return record

@app.route("/api/history", methods=["GET"])
def api_get_history():
    ws_id = get_workspace_id()
    try:
        cleanup_expired_history(ws_id, max_days=HISTORY_RETENTION_DAYS)
    except Exception:
        pass
    items = load_workspace_history(ws_id)
    now_dt = datetime.now()
    result = []
    for it in items:
        exp_str = it.get("expires_at")
        days_left = HISTORY_RETENTION_DAYS
        if exp_str:
            try:
                exp_dt = datetime.fromisoformat(exp_str)
                diff = (exp_dt - now_dt).total_seconds()
                days_left = max(0, int(diff // 86400))
            except Exception:
                pass
        it_copy = dict(it)
        it_copy["days_left"] = days_left
        result.append(it_copy)
    return jsonify({"status": "ok", "history": result, "retention_days": HISTORY_RETENTION_DAYS})

@app.route("/api/history/<hist_id>", methods=["DELETE"])
def api_delete_history(hist_id):
    ws_id = get_workspace_id()
    items = load_workspace_history(ws_id)
    new_items = []
    for it in items:
        if it.get("id") == hist_id:
            fpath = it.get("file_path")
            if fpath and os.path.exists(fpath):
                try: os.remove(fpath)
                except Exception: pass
        else:
            new_items.append(it)
    save_workspace_history(ws_id, new_items)
    return jsonify({"status": "ok"})

@app.route("/api/workspace/video/stream")
def api_workspace_video_stream():
    ws_id = request.args.get("ws") or get_workspace_id()
    fname = request.args.get("file", "output_vietsub.mp4")
    safe_name = os.path.basename(fname)
    ws_dir = os.path.join(WORKSPACES_ROOT, f"ws_{ws_id}")
    fpath = os.path.join(ws_dir, safe_name)
    if not os.path.exists(fpath):
        fpath = os.path.join(TEMP_DIR, safe_name)
    if not os.path.exists(fpath):
        return jsonify({"error": "Video không tồn tại"}), 404
    return send_file(fpath, mimetype="video/mp4")

@app.route("/api/workspace/video/download")
def api_workspace_video_download():
    ws_id = request.args.get("ws") or get_workspace_id()
    fname = request.args.get("file", "output_vietsub.mp4")
    safe_name = os.path.basename(fname)
    ws_dir = os.path.join(WORKSPACES_ROOT, f"ws_{ws_id}")
    fpath = os.path.join(ws_dir, safe_name)
    if not os.path.exists(fpath):
        fpath = os.path.join(TEMP_DIR, safe_name)
    if not os.path.exists(fpath):
        return jsonify({"error": "Video không tồn tại"}), 404
    return send_file(fpath, as_attachment=True, download_name=safe_name)

def get_workspace_cloud_config_path(ws_id=None):
    if not ws_id:
        try:
            ws_id = get_workspace_id()
        except Exception:
            ws_id = "default"
    ws_dir = os.path.join(WORKSPACES_ROOT, f"ws_{ws_id}")
    os.makedirs(ws_dir, exist_ok=True)
    return os.path.join(ws_dir, "cloud_config.json")

def load_cloud_config(ws_id=None):
    """
    Nạp cấu hình Kaggle, GitHub và Gemini API của RIÊNG người dùng / workspace hiện tại.
    """
    cfg_path = get_workspace_cloud_config_path(ws_id)
    default_cfg = {
        "kaggle_username": "",
        "kaggle_key": "",
        "kaggle_kernel_slug": "nexus-vietsub-worker",
        "github_token": "",
        "github_repo": "Tridung-boop/nexus-worker2",
        "github_codespace_name": "",
        "gemini_keys": "",
        "gemini_model": "gemini-3.5-flash"
    }
    # 1. Đọc file cấu hình riêng của workspace
    if os.path.exists(cfg_path):
        try:
            with open(cfg_path, "r", encoding="utf-8") as f:
                saved = json.load(f)
                for k, v in saved.items():
                    if v is not None:
                        default_cfg[k] = v
        except Exception:
            pass
    # 2. Nếu workspace mới chưa cấu hình, fallback sang file global làm mẫu ban đầu
    elif os.path.exists(CLOUD_CONFIG_FILE):
        try:
            with open(CLOUD_CONFIG_FILE, "r", encoding="utf-8") as f:
                saved = json.load(f)
                for k, v in saved.items():
                    if v is not None and not default_cfg.get(k):
                        default_cfg[k] = v
        except Exception:
            pass

    # 3. Biến môi trường hệ thống (Railway) nếu người dùng có khai báo
    for env_k, cfg_k in [
        ("GITHUB_TOKEN", "github_token"),
        ("GITHUB_REPO", "github_repo"),
        ("KAGGLE_USERNAME", "kaggle_username"),
        ("KAGGLE_KEY", "kaggle_key"),
        ("KAGGLE_KERNEL_SLUG", "kaggle_kernel_slug"),
        ("GITHUB_CODESPACE_NAME", "github_codespace_name"),
        ("GEMINI_API_KEY", "gemini_keys")
    ]:
        val = os.environ.get(env_k)
        if val and val.strip() and not default_cfg.get(cfg_k):
            default_cfg[cfg_k] = val.strip()
    return default_cfg

def save_cloud_config(cfg, ws_id=None):
    """
    Lưu cấu hình Kaggle, GitHub, Gemini API vào workspace của RIÊNG người dùng này.
    """
    cfg_path = get_workspace_cloud_config_path(ws_id)
    cur = load_cloud_config(ws_id)
    for k in ["kaggle_username", "kaggle_key", "kaggle_kernel_slug", "github_token", "github_repo", "github_codespace_name", "gemini_keys", "gemini_model"]:
        if k in cfg:
            cur[k] = str(cfg[k]).strip()
    try:
        with open(cfg_path, "w", encoding="utf-8") as f:
            json.dump(cur, f, ensure_ascii=False, indent=2)
        if not ws_id or ws_id == "default":
            with open(CLOUD_CONFIG_FILE, "w", encoding="utf-8") as f:
                json.dump(cur, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[!] Lỗi lưu cloud config workspace {ws_id}: {e}", flush=True)
    return cur
    with open(CLOUD_CONFIG_FILE, "w", encoding="utf-8") as f:
        json.dump(current, f, ensure_ascii=False, indent=2)
    return current

# ==================== MODULE 7: MÃ NGUỒN TỰ HÀNH CLOUD WORKER (KÈM DVD WATERMARK & LOGO) ====================
CLOUD_WORKER_SCRIPT_TEMPLATE = r'''import os, sys, re, time, json, math, site, shutil, tarfile, hashlib, asyncio, importlib, subprocess, ctypes, wave, threading
from concurrent.futures import ThreadPoolExecutor, as_completed

RELAY_URL = "__RELAY_URL__"
JOB_ID = "__JOB_ID__"
GH_TOKEN = "__GH_TOKEN__"
GH_CODESPACE = "__GH_CODESPACE__"

def ensure_requests():
    try:
        import requests
        return requests
    except ImportError:
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "requests"], check=False)
        importlib.invalidate_caches()
        import requests
        return requests

requests = ensure_requests()

_LAST_PROGRESS_TIME = 0.0
_LAST_PROGRESS_PCT = -1

def report_progress(pct, msg, segments=None, locked_context=None, force=False, gofile_url=None, direct_url=None):
    global _LAST_PROGRESS_TIME, _LAST_PROGRESS_PCT
    now = time.time()
    # Throttle progress reports: don't flood HTTP requests unless forced or has payload
    if not force and segments is None and locked_context is None and gofile_url is None and direct_url is None:
        if pct == _LAST_PROGRESS_PCT and (now - _LAST_PROGRESS_TIME) < 4.0:
            return
        if (now - _LAST_PROGRESS_TIME) < 2.5 and pct < 100:
            return
    _LAST_PROGRESS_TIME = now
    _LAST_PROGRESS_PCT = pct
    print(f"[CLOUD WORKER {pct}%] {msg}", flush=True)
    payload = {"job_id": JOB_ID, "percent": pct, "message": f"☁️ [Cloud] {msg}"}
    if segments is not None:
        payload["segments"] = segments
    if locked_context is not None:
        payload["locked_context"] = locked_context
    if gofile_url:
        payload["gofile_url"] = gofile_url
    if direct_url:
        payload["direct_url"] = direct_url
    try:
        requests.post(f"{RELAY_URL}/api/relay/progress", json=payload, timeout=10)
    except Exception as e:
        print(f"[!] Lỗi báo cáo tiến độ: {e}")

def preload_cuda():
    if os.name == "nt": return
    try:
        for sdir in site.getsitepackages() + [site.getusersitepackages()]:
            ndir = os.path.join(sdir, "nvidia")
            if os.path.exists(ndir):
                for root, _, files in os.walk(ndir):
                    for lib in ["libcublas.so.12", "libcublasLt.so.12", "libcudnn.so.9", "libcudnn.so.8", "libcudnn_ops.so.9", "libcudnn_cnn.so.9"]:
                        if lib in files:
                            try: ctypes.CDLL(os.path.join(root, lib), mode=ctypes.RTLD_GLOBAL)
                            except Exception: pass
    except Exception: pass

def install_dependencies():
    report_progress(3, "Đang cài đặt FFmpeg, Font Đa Ngôn Ngữ & Thư viện AI trên Cloud...")
    if shutil.which("apt-get"):
        sudo_prefix = ["sudo"] if (hasattr(os, "geteuid") and os.geteuid() != 0 and shutil.which("sudo")) else []
        subprocess.run(sudo_prefix + ["apt-get", "update", "-qq"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        subprocess.run(sudo_prefix + ["apt-get", "install", "-y", "-qq", "ffmpeg", "fonts-liberation", "fonts-noto-core", "fonts-noto-cjk", "fontconfig"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        subprocess.run(sudo_prefix + ["fc-cache", "-f"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    pkgs = ["av", "faster-whisper", "edge-tts", "pydub", "Pillow", "requests", "numpy", "audioop-lts"]
    res = subprocess.run([sys.executable, "-m", "pip", "install", "-q"] + pkgs, capture_output=True, text=True)
    if res.returncode != 0:
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--break-system-packages"] + pkgs, capture_output=True, text=True)

    importlib.invalidate_caches()
    user_site = site.getusersitepackages()
    if user_site not in sys.path:
        sys.path.insert(0, user_site)
    for sp in site.getsitepackages():
        if sp not in sys.path:
            sys.path.insert(0, sp)
    preload_cuda()

def setup_cloud_piper(work_dir, voice_id):
    piper_dir = os.path.join(work_dir, "piper_bin")
    piper_exe = os.path.join(piper_dir, "piper", "piper")
    if not os.path.exists(piper_exe):
        try:
            os.makedirs(piper_dir, exist_ok=True)
            tgz = os.path.join(piper_dir, "piper.tar.gz")
            r = requests.get("https://github.com/rhasspy/piper/releases/download/2023.11.14-2/piper_linux_x86_64.tar.gz", stream=True, timeout=90)
            with open(tgz, "wb") as f:
                for c in r.iter_content(65536):
                    if c: f.write(c)
            with tarfile.open(tgz, "r:gz") as tf:
                tf.extractall(piper_dir)
            if os.path.exists(piper_exe):
                os.chmod(piper_exe, 0o755)
        except Exception as e_p:
            print(f"[!] Lỗi tải bộ Piper Linux: {e_p}")

    model_name = voice_id.replace("piper:", "").strip()
    m_dir = os.path.join(work_dir, "piper_models")
    os.makedirs(m_dir, exist_ok=True)
    onnx_p = os.path.join(m_dir, f"{model_name}.onnx")
    json_p = os.path.join(m_dir, f"{model_name}.onnx.json")

    if not os.path.exists(onnx_p):
        parts = model_name.split("-")
        if len(parts) >= 3:
            locale = parts[0]
            lang_s = locale.split("_")[0]
            qual = parts[-1]
            spk = "-".join(parts[1:-1])
            hf_base = f"https://huggingface.co/rhasspy/piper-voices/resolve/v1.0.0/{lang_s}/{locale}/{spk}/{qual}/{model_name}"
            rj = requests.get(f"{hf_base}.onnx.json", timeout=30)
            if rj.status_code == 200:
                with open(json_p, "wb") as f: f.write(rj.content)
                ro = requests.get(f"{hf_base}.onnx", stream=True, timeout=180)
                with open(onnx_p, "wb") as f:
                    for c in ro.iter_content(131072):
                        if c: f.write(c)

        if not os.path.exists(onnx_p):
            rj = requests.get(f"{RELAY_URL}/api/relay/piper_model/{model_name}.onnx.json", timeout=30)
            if rj.status_code == 200:
                with open(json_p, "wb") as f: f.write(rj.content)
            ro = requests.get(f"{RELAY_URL}/api/relay/piper_model/{model_name}.onnx", stream=True, timeout=180)
            if ro.status_code == 200:
                with open(onnx_p, "wb") as f:
                    for c in ro.iter_content(131072):
                        if c: f.write(c)

    return piper_exe, onnx_p

def probe_video_info(video_path):
    try:
        import av
        with av.open(video_path) as container:
            vstream = container.streams.video[0]
            vid_w, vid_h = vstream.width, vstream.height
            total_dur = float(container.duration / av.time_base) if container.duration else 0.0
            has_audio = len(container.streams.audio) > 0
            return vid_w, vid_h, total_dur, has_audio
    except Exception:
        cmd = ["ffprobe", "-v", "quiet", "-print_format", "json", "-show_format", "-show_streams", video_path]
        proc = subprocess.run(cmd, capture_output=True, text=True)
        info = json.loads(proc.stdout or "{}")
        vid_w, vid_h, has_audio = 1280, 720, False
        for s in info.get("streams", []):
            if s.get("codec_type") == "video":
                vid_w = int(s.get("width", 1280))
                vid_h = int(s.get("height", 720))
            elif s.get("codec_type") == "audio":
                has_audio = True
        total_dur = float(info.get("format", {}).get("duration", 0.0))
        return vid_w, vid_h, total_dur, has_audio

def detect_sub_blur_area(video_path, vid_w, vid_h):
    try:
        import av
        import numpy as np
        with av.open(video_path) as container:
            stream = container.streams.video[0]
            stream.thread_type = "AUTO"
            total_dur = float(container.duration / av.time_base) if container.duration else 180.0
            scan_limit = min(total_dur, 180.0)
            y_top = int(vid_h * 0.55)
            y_bot = int(vid_h * 0.96)
            roi_h = y_bot - y_top
            sample_step = max(0.5, scan_limit / 80.0)
            next_t = 0.0
            row_energy = np.zeros(roi_h, dtype=np.float64)
            active_cnt = 0
            for frame in container.decode(stream):
                if frame.pts is None: continue
                t = float(frame.pts * stream.time_base)
                if t < next_t: continue
                if t > scan_limit: break
                next_t = t + sample_step
                img = frame.to_ndarray(format="rgb24")
                xl, xr = int(vid_w * 0.15), int(vid_w * 0.85)
                roi = img[y_top:y_bot, xl:xr]
                gray = (0.299 * roi[..., 0] + 0.587 * roi[..., 1] + 0.114 * roi[..., 2]).astype(np.float32)
                grad_x = np.abs(np.diff(gray, axis=1))
                edges = np.mean(grad_x > 30.0, axis=1)
                if np.max(edges) > 0.04:
                    row_energy += edges
                    active_cnt += 1
            if active_cnt >= 2 and np.max(row_energy) > 0:
                kernel = np.ones(5) / 5.0
                smoothed = np.convolve(row_energy / active_cnt, kernel, mode="same")
                peak = int(np.argmax(smoothed))
                thresh = float(smoothed[peak]) * 0.25
                top = peak
                while top > 0 and smoothed[top] >= thresh: top -= 1
                bot = peak
                while bot < roi_h - 1 and smoothed[bot] >= thresh: bot += 1
                pad = 22
                real_y1 = max(0, y_top + top - pad)
                real_y2 = min(vid_h, y_top + bot + pad)
                min_h = max(50, int(vid_h * 0.16)) // 2 * 2
                if (real_y2 - real_y1) < min_h:
                    mid_y = (real_y1 + real_y2) // 2
                    real_y1 = max(0, mid_y - min_h // 2)
                    real_y2 = min(vid_h, real_y1 + min_h)
                h = max(min_h, real_y2 - real_y1) // 2 * 2
                y = min(real_y1, vid_h - h) // 2 * 2
                return {"x": 0, "y": y, "w": vid_w // 2 * 2, "h": h}
    except Exception as e_scan:
        print(f"[!] Auto scan sub notice: {e_scan}", flush=True)
    def_h = int(vid_h * 0.18) // 2 * 2
    def_y = int(vid_h * 0.74) // 2 * 2
    return {"x": 0, "y": def_y, "w": vid_w // 2 * 2, "h": def_h}

def format_srt_time(seconds):
    seconds = max(0.0, float(seconds or 0.0))
    hrs = int(seconds // 3600)
    mins = int((seconds % 3600) // 60)
    secs = int(seconds % 60)
    msecs = min(999, int(round((seconds - int(seconds)) * 1000)))
    return f"{hrs:02d}:{mins:02d}:{secs:02d},{msecs:03d}"

def format_ass_time(seconds):
    seconds = max(0.0, float(seconds or 0.0))
    hrs = int(seconds // 3600)
    mins = int((seconds % 3600) // 60)
    secs = int(seconds % 60)
    cs = min(99, int(round((seconds - int(seconds)) * 100)))
    return f"{hrs:d}:{mins:02d}:{secs:02d}.{cs:02d}"

def hex_to_ass_color(hex_color, alpha=0):
    hex_color = (hex_color or "#FFFFFF").lstrip('#')
    if len(hex_color) != 6: hex_color = "FFFFFF"
    return f"&H{alpha:02X}{hex_color[4:6].upper()}{hex_color[2:4].upper()}{hex_color[0:2].upper()}"

def generate_ass(ass_path, segments, vid_w, vid_h, st, addon_cfg, total_dur):
    play_res_y = 720
    play_res_x = int(round(720 * (vid_w / max(1, vid_h))))
    ass_primary = hex_to_ass_color(st.get("textColor", "#FFFFFF"), 0)
    ass_outline = hex_to_ass_color(st.get("outlineColor", "#000000"), 0)
    ass_font_size = int(round(int(st.get("fontSize", 22)) * 1.28))
    font_name = st.get("fontName", "Arial")
    target_lang = st.get("targetLang", "vi")
    if target_lang in ("zh", "ja", "ko"):
        font_name = "Noto Sans CJK SC"
    elif font_name in ("Arial", "Tahoma", "Verdana", "Calibri"):
        font_name = "Liberation Sans"
    outline_w = int(st.get("outlineWidth", 2))
    margin_v = int(st.get("marginV", 28))
    border_style = 1
    outline_val = outline_w
    back_colour = "&H80000000"

    dvd_style_line = ""
    if addon_cfg.get("dvd_text_enabled"):
        d_font = int(addon_cfg.get("dvd_font_size", 24))
        d_op = float(addon_cfg.get("dvd_opacity", 35))
        d_alpha = max(0, min(250, int(round((100.0 - max(5.0, min(100.0, d_op))) * 2.55))))
        d_col = hex_to_ass_color(addon_cfg.get("dvd_color", "#FFFFFF"), d_alpha)
        d_out = hex_to_ass_color("#000000", min(250, d_alpha + 40))
        dvd_style_line = f"Style: DVDWatermark,{font_name},{d_font},{d_col},{d_col},{d_out},&HFF000000,-1,0,0,0,100,100,1,0,1,1,0,5,10,10,10,1\n"

    header = f"""[Script Info]
ScriptType: v4.00+
WrapStyle: 0
ScaledBorderAndShadow: yes
YCbCr Matrix: TV.709
PlayResX: {play_res_x}
PlayResY: {play_res_y}

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,{font_name},{ass_font_size},{ass_primary},&H000000FF,{ass_outline},{back_colour},-1,0,0,0,100,100,0,0,{border_style},{outline_val},0,2,25,25,{margin_v},1
{dvd_style_line}
[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
"""
    with open(ass_path, "w", encoding="utf-8") as f:
        f.write(header)
        for seg in segments:
            txt = (seg.get("trans") or seg.get("text") or "").strip().replace("\n", "\\N")
            if txt:
                f.write(f"Dialogue: 0,{format_ass_time(seg['start'])},{format_ass_time(seg['end'])},Default,,0,0,0,,{txt}\n")

        # Nếu bật chữ mờ chạy kiểu DVD trên Cloud
        if addon_cfg.get("dvd_text_enabled") and (addon_cfg.get("dvd_text") or "").strip():
            d_txt = addon_cfg.get("dvd_text").strip().replace("\n", " ")
            d_size = int(addon_cfg.get("dvd_font_size", 24))
            speed = max(30.0, float(addon_cfg.get("dvd_speed", 120)))
            mx = max(80, min(play_res_x // 3, len(d_txt) * (d_size // 3)))
            my = max(35, d_size + 10)
            min_x, max_x = mx, max(mx + 50, play_res_x - mx)
            min_y, max_y = my, max(my + 50, play_res_y - my)
            cx, cy = min_x + 40, min_y + 40
            vx, vy = speed * 0.82, speed * 0.58
            ct = 0.0
            max_t = max(10.0, float(total_dur or 300.0))
            while ct < max_t:
                tx = (max_x - cx) / vx if vx > 0 else (min_x - cx) / vx
                ty = (max_y - cy) / vy if vy > 0 else (min_y - cy) / vy
                dt = max(0.5, min(tx, ty))
                if ct + dt > max_t: dt = max_t - ct
                nx, ny = int(round(cx + vx * dt)), int(round(cy + vy * dt))
                f.write(f"Dialogue: 1,{format_ass_time(ct)},{format_ass_time(ct+dt)},DVDWatermark,,0,0,0,,{{\\an5\\move({int(cx)},{int(cy)},{nx},{ny})}}{d_txt}\n")
                cx, cy = nx, ny
                ct += dt
                if abs(tx - ty) < 0.05: vx, vy = -vx, -vy
                elif tx < ty: vx = -vx
                else: vy = -vy

def translate_google_batch_cloud(items, target_lang='vi'):
    if not items: return {}
    res_map = {}
    batch_size = 25
    chunks = [items[i:i+batch_size] for i in range(0, len(items), batch_size)]
    headers = {"User-Agent": "Mozilla/5.0"}
    for ch in chunks:
        encoded = "\n".join([f"[[ID_{sid}]] {txt}" for sid, txt in ch if txt.strip()])
        if not encoded.strip(): continue
        try:
            url = "https://translate.googleapis.com/translate_a/single"
            params = {"client": "gtx", "sl": "auto", "tl": target_lang, "dt": "t", "q": encoded}
            r = requests.get(url, params=params, headers=headers, timeout=12)
            if r.status_code == 200:
                raw_t = "".join([p[0] for p in r.json()[0] if p and p[0]])
                matches = re.finditer(r'\[\[ID_(\d+)\]\]\s*(.*?)(?=\[\[ID_\d+\]\]|$|\n)', raw_t, re.DOTALL)
                for m in matches:
                    sid = int(m.group(1))
                    val = m.group(2).strip()
                    if val: res_map[sid] = val
        except Exception: pass
    for sid, txt in items:
        if sid not in res_map and txt.strip():
            try:
                url = "https://translate.googleapis.com/translate_a/single"
                params = {"client": "gtx", "sl": "auto", "tl": target_lang, "dt": "t", "q": txt}
                r = requests.get(url, params=params, headers=headers, timeout=6)
                if r.status_code == 200:
                    val = "".join([p[0] for p in r.json()[0] if p and p[0]]).strip()
                    if val: res_map[sid] = val
            except Exception: pass
    return res_map

def call_gemini(api_keys, idx, model_pref, prompt):
    valid_models = []
    for m in [model_pref, "gemini-3.5-flash", "gemini-3.5-flash-lite", "gemini-3.8-flash", "gemini-2.5-flash", "gemini-2.0-flash", "gemini-1.5-flash"]:
        if m and m not in valid_models:
            valid_models.append(m)
    base_payload = {"contents": [{"parts": [{"text": prompt}]}], "generationConfig": {"temperature": 0.15}}
    for k_off in range(len(api_keys)):
        key = api_keys[(idx + k_off) % len(api_keys)]
        for m in valid_models:
            url = f"https://generativelanguage.googleapis.com/v1beta/models/{m}:generateContent?key={key}"
            try:
                pl = json.loads(json.dumps(base_payload))
                if "thinking" in m:
                    pl["generationConfig"]["thinkingConfig"] = {"thinkingBudget": 0}
                r = requests.post(url, json=pl, timeout=90)
                if r.status_code == 400 and "thinkingConfig" in r.text:
                    r = requests.post(url, json=base_payload, timeout=90)
                if r.status_code == 200:
                    return r.json()
                elif r.status_code == 429:
                    break
            except Exception:
                continue
    return None

def run_worker():
    install_dependencies()
    import edge_tts
    from pydub import AudioSegment

    work_dir = os.path.abspath("nexus_cloud_work")
    os.makedirs(work_dir, exist_ok=True)
    video_path = os.path.join(work_dir, "input_video.mp4")

    report_progress(6, "Đang tải cấu hình & Video gốc từ Trạm Trung Chuyển...")
    cfg_resp = requests.get(f"{RELAY_URL}/api/relay/job/{JOB_ID}/config", timeout=30).json()
    task_mode = cfg_resp.get("task_mode", "full")
    segments = cfg_resp.get("segments", [])
    st = cfg_resp.get("settings", {})
    addon_cfg = cfg_resp.get("addon_settings", {})
    has_logo_remote = cfg_resp.get("has_logo", False)
    api_keys = cfg_resp.get("apiKeys", [])
    gemini_model = cfg_resp.get("geminiModel", "gemini-3.5-flash")
    whisper_model = cfg_resp.get("whisperModel", "small")
    target_lang_label = st.get("targetLangLabel", "Tiếng Việt")
    google_lang_code = st.get("googleLangCode", "vi")

    with requests.get(f"{RELAY_URL}/api/relay/job/{JOB_ID}/video", stream=True, timeout=300) as r:
        r.raise_for_status()
        with open(video_path, "wb") as f:
            for chunk in r.iter_content(chunk_size=1024*1024):
                if chunk: f.write(chunk)

    logo_path = os.path.join(work_dir, "watermark_logo.png")
    if has_logo_remote and addon_cfg.get("logo_enabled"):
        try:
            rl = requests.get(f"{RELAY_URL}/api/relay/job/{JOB_ID}/logo", timeout=30)
            if rl.status_code == 200:
                with open(logo_path, "wb") as f:
                    f.write(rl.content)
        except Exception:
            pass

    vid_w, vid_h, total_dur, has_audio = probe_video_info(video_path)

    # BƯỚC 1: TÁCH SUB TRÊN CLOUD
    if not segments or task_mode == "transcribe":
        from faster_whisper import WhisperModel
        import ctranslate2
        cuda_cnt = ctranslate2.get_cuda_device_count()
        if cuda_cnt > 0:
            dev_idx = list(range(cuda_cnt)) if cuda_cnt > 1 else 0
            report_progress(14, f"Đang khởi tạo Whisper ({whisper_model}) trên {cuda_cnt}x GPU T4 CUDA...")
            w_model = WhisperModel(whisper_model, device="cuda", device_index=dev_idx, compute_type="float16")
        else:
            report_progress(14, f"Đang khởi tạo Whisper ({whisper_model}) trên Cloud CPU ({os.cpu_count()} luồng)...")
            w_model = WhisperModel(whisper_model, device="cpu", compute_type="int8", cpu_threads=os.cpu_count() or 4)

        wav_16k = os.path.join(work_dir, "audio_16k.wav")
        subprocess.run(["ffmpeg", "-y", "-i", video_path, "-vn", "-acodec", "pcm_s16le", "-ar", "16000", "-ac", "1", wav_16k], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        transcribe_input = wav_16k if os.path.exists(wav_16k) else video_path

        raw_segs, _ = w_model.transcribe(transcribe_input, beam_size=5)
        segments = []
        for idx, s in enumerate(raw_segs, start=1):
            segments.append({"id": idx, "start": round(s.start, 2), "end": round(s.end, 2), "text": s.text.strip(), "trans": ""})
            if idx % 3 == 0 or idx == 1:
                pct = 15 + (int((s.end / total_dur) * 20) if total_dur > 0 else min(20, idx))
                report_progress(min(35, pct), f"Đã tách câu #{idx}: {s.text[:25]}...", segments=segments)

        report_progress(36, f"Hoàn tất tách {len(segments)} câu phụ đề trên Cloud!", segments=segments)
        if task_mode == "transcribe":
            requests.post(f"{RELAY_URL}/api/relay/complete/{JOB_ID}", json={"segments": segments}, timeout=30)
            return

    # BƯỚC 2: DỊCH ĐA NGÔN NGỮ ĐỒNG BỘ NGỮ CẢNH TRÊN CLOUD (HỖ TRỢ GEMINI + AUTO GOOGLE FALLBACK)
    untranslated = [i for i, s in enumerate(segments) if not (s.get("trans") or "").strip()] or list(range(len(segments)))
    if untranslated and task_mode != "render_only":
        report_progress(40, f"Đang dịch sang [{target_lang_label}] (Gemini AI & Google Auto-Fallback)...")
        locked_ctx = st.get("contextGlossary", "")
        if api_keys:
            sample_txt = "\n".join([f"{s['id']}. {s['text']}" for s in segments[::max(1, len(segments)//35)][:40]])
            bible_prompt = (
                f"Lập BẢNG QUY CHUẨN NGỮ CẢNH ngắn gọn (<100 từ) để dịch kịch bản sau sang ngôn ngữ đích là [{target_lang_label}]:\n"
                f"- Quy tắc xưng hô/văn phong: {st.get('pronounRule', 'auto')}\n"
                f"- Ghi chú: {st.get('contextGlossary', '')}\n"
                f"Trả về 3 dòng: 1. Chủ đề, 2. Xưng hô/Văn phong bắt buộc trong {target_lang_label}, 3. Thuật ngữ:\n{sample_txt}"
            )
            bible_res = call_gemini(api_keys, 0, gemini_model, bible_prompt)
            if bible_res:
                try: locked_ctx = bible_res["candidates"][0]["content"]["parts"][0]["text"].strip()
                except Exception: pass

        batch_size = 18
        idx_batches = [untranslated[i:i+batch_size] for i in range(0, len(untranslated), batch_size)]
        seg_map = {s["id"]: s for s in segments}

        def trans_batch(b_idx, idx_list):
            batch_items = [(segments[i]['id'], segments[i]['text']) for i in idx_list]
            r_json = None
            if api_keys:
                f_i, l_i = idx_list[0], idx_list[-1]
                prev_s = "\n".join([f"[Trước] {s['text']}" for s in segments[max(0, f_i-3):f_i]])
                lines_in = "\n".join([f"[[ID_{segments[i]['id']}]] {segments[i]['text']}" for i in idx_list])
                p = (
                    f"Dịch các câu phụ đề sau sang ngôn ngữ đích là [{target_lang_label}] chuẩn ngữ cảnh & khớp thời lượng đọc lồng tiếng.\n"
                    f"QUY CHUẨN BẮT BUỘC:\n{locked_ctx}\n"
                    f"CÂU TRƯỚC ĐÓ:\n{prev_s}\n"
                    f"CHỈ TRẢ VỀ ĐỊNH DẠNG: [[ID_X]] Bản dịch bằng {target_lang_label}\n\n{lines_in}"
                )
                r_json = call_gemini(api_keys, b_idx, gemini_model, p)
            return b_idx, r_json, batch_items

        done_b = 0
        workers_cnt = min(len(idx_batches), max(2, len(api_keys)*2 if api_keys else 4))
        with ThreadPoolExecutor(max_workers=workers_cnt) as ex:
            futs = [ex.submit(trans_batch, idx, ib) for idx, ib in enumerate(idx_batches)]
            for fut in as_completed(futs):
                b_idx, r_json, b_items = fut.result()
                done_b += 1
                batch_expected = {item[0] for item in b_items}
                batch_res = {}
                if r_json:
                    try:
                        raw_t = r_json["candidates"][0]["content"]["parts"][0]["text"].strip()
                        matches = re.finditer(r'\[\[ID_(\d+)\]\]\s*(.*?)(?=\[\[ID_\d+\]\]|$|\n)', raw_t, re.DOTALL)
                        for m in matches:
                            sid = int(m.group(1))
                            val = m.group(2).strip()
                            if val and sid in batch_expected: batch_res[sid] = val
                        for line in raw_t.split("\n"):
                            line = line.strip()
                            if not line: continue
                            lm = re.match(r'^(?:\[\s*|ID\s*|#\s*)?(\d+)(?:\])?\s*[\:\.\|\-\t\uff5c\uff1a]\s*(.+)$', line)
                            if lm:
                                sid = int(lm.group(1))
                                val = lm.group(2).strip()
                                if sid in batch_expected and sid not in batch_res and val:
                                    batch_res[sid] = val
                    except Exception: pass
                # Google Translate fallback cho các câu còn thiếu
                missing_items = [it for it in b_items if it[0] not in batch_res]
                if missing_items:
                    g_fallback = translate_google_batch_cloud(missing_items, target_lang=google_lang_code)
                    batch_res.update(g_fallback)
                for sid, t_val in batch_res.items():
                    if sid in seg_map and t_val:
                        seg_map[sid]["trans"] = t_val
                pct = 42 + int((done_b / max(1, len(idx_batches))) * 18)
                report_progress(pct, f"Đã dịch sang {target_lang_label} ({done_b}/{len(idx_batches)} lô)...", segments=segments, locked_context=locked_ctx)

    # BƯỚC 3: TẠO GIỌNG ĐỌC ĐA NGÔN NGỮ (PIPER NEURAL ONNX / EDGE AI / GOOGLE TTS) TRÊN CLOUD
    tts_dir = os.path.join(work_dir, "tts")
    os.makedirs(tts_dir, exist_ok=True)
    final_audio = os.path.join(work_dir, "mixed_audio.wav")
    enable_tts = st.get("enableTts", True)
    tts_voice = st.get("ttsVoice", "piper:vi_VN-vais1000-medium")
    orig_vol = float(st.get("origVolume", 15)) / 100.0
    video_input_name = "input_video.mp4"

    if enable_tts:
        done_tts = 0
        total_tts = len(segments)
        tts_lock = threading.Lock()

        if tts_voice.startswith("piper:"):
            report_progress(62, f"Đang tải nhân Piper Neural ONNX ({tts_voice}) trên Cloud...", force=True)
            piper_exe, onnx_path = setup_cloud_piper(work_dir, tts_voice)
            piper_env = os.environ.copy()
            piper_dir_bin = os.path.dirname(piper_exe)
            piper_env["LD_LIBRARY_PATH"] = f"{piper_dir_bin}:{piper_env.get('LD_LIBRARY_PATH', '')}"

            def run_piper_one(seg):
                nonlocal done_tts
                txt = (seg.get("trans") or seg.get("text") or "").strip()
                if not txt: return
                out_wav = os.path.join(tts_dir, f"s_{seg['id']}.wav")
                if not (os.path.exists(out_wav) and os.path.getsize(out_wav) > 100):
                    if os.path.exists(piper_exe) and os.path.exists(onnx_path):
                        try:
                            subprocess.run([piper_exe, "--model", onnx_path, "--output_file", out_wav], input=txt.encode("utf-8"), env=piper_env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                        except Exception: pass
                    # Fallback sang Google TTS nếu Piper lỗi trên môi trường Cloud
                    if not os.path.exists(out_wav) or os.path.getsize(out_wav) < 100:
                        try:
                            g_r = requests.get("https://translate.googleapis.com/translate_tts", params={"ie":"UTF-8","q":txt[:200],"tl":google_lang_code,"client":"tw-ob"}, timeout=10)
                            if g_r.status_code == 200:
                                with open(out_wav.replace(".wav", ".mp3"), "wb") as f_g:
                                    f_g.write(g_r.content)
                        except Exception: pass
                with tts_lock:
                    done_tts += 1
                    if done_tts % 50 == 0 or done_tts == total_tts:
                        p_val = 62 + int((done_tts / max(1, total_tts)) * 9)
                        report_progress(p_val, f"Đang tạo giọng đọc Piper ({done_tts}/{total_tts} câu)...")

            worker_threads = min(4, max(2, os.cpu_count() or 2))
            with ThreadPoolExecutor(max_workers=worker_threads) as ex:
                list(ex.map(run_piper_one, segments))
        else:
            report_progress(62, f"Đang tạo giọng đọc đa luồng ({tts_voice}) trên Cloud...", force=True)
            async def make_tts():
                nonlocal done_tts
                sem = asyncio.Semaphore(16)
                async def one_tts(seg):
                    nonlocal done_tts
                    txt = (seg.get("trans") or seg.get("text") or "").strip()
                    if not txt: return
                    out_f = os.path.join(tts_dir, f"s_{seg['id']}.mp3")
                    async with sem:
                        ok = False
                        if not tts_voice.startswith("google:"):
                            for _ in range(2):
                                try:
                                    comm = edge_tts.Communicate(txt, tts_voice)
                                    await asyncio.wait_for(comm.save(out_f), timeout=12)
                                    if os.path.exists(out_f) and os.path.getsize(out_f) > 100:
                                        ok = True; break
                                except Exception: pass
                        if not ok:
                            g_tl = tts_voice.split(":", 1)[1] if tts_voice.startswith("google:") else google_lang_code
                            try:
                                r = requests.get("https://translate.googleapis.com/translate_tts", params={"ie":"UTF-8","q":txt[:200],"tl":g_tl,"client":"tw-ob"}, timeout=10)
                                if r.status_code == 200:
                                    with open(out_f, "wb") as f: f.write(r.content)
                            except Exception: pass
                    with tts_lock:
                        done_tts += 1
                        if done_tts % 50 == 0 or done_tts == total_tts:
                            p_val = 62 + int((done_tts / max(1, total_tts)) * 9)
                            report_progress(p_val, f"Đang tạo giọng đọc đa luồng ({done_tts}/{total_tts} câu)...")
                await asyncio.gather(*[one_tts(s) for s in segments])
            asyncio.run(make_tts())

        sync_mode = st.get("syncMode", "retime_video")
        # Video dài (>150 câu hoặc >600s) tự động dùng atempo để đảm bảo ổn định 100%, chống tràn RAM và sập filter FFmpeg
        if sync_mode == "retime_video" and (len(segments) > 150 or total_dur > 600):
            print(f"[RETIME GUARD] Video dài ({len(segments)} câu, {total_dur:.0f}s). Tự động dùng chế độ atempo đồng bộ audio siêu tốc để đảm bảo ổn định 100%!", flush=True)
            sync_mode = "atempo"

        audio_clips_path = {}
        for seg in segments:
            c_p = os.path.join(tts_dir, f"s_{seg['id']}.wav")
            if not os.path.exists(c_p):
                c_p = os.path.join(tts_dir, f"s_{seg['id']}.mp3")
            if os.path.exists(c_p):
                audio_clips_path[seg["id"]] = c_p

        # CHẾ ĐỘ 1: CO GIÃN VIDEO THEO CÂU NÓI (CHO VIDEO NGẮN < 150 CÂU)
        if sync_mode == "retime_video" and audio_clips_path:
            report_progress(74, "Đang tính toán timeline co giãn Video theo từng câu nói...", force=True)
            intervals = []
            cur_orig = 0.0
            new_timeline = 0.0
            new_segments = []

            for seg in segments:
                s_start, s_end = float(seg["start"]), float(seg["end"])
                if s_start > cur_orig:
                    gap_dur = s_start - cur_orig
                    intervals.append({"t0": cur_orig, "t1": s_start, "mult": 1.0, "out_dur": gap_dur})
                    new_timeline += gap_dur
                    cur_orig = s_start

                v_dur = max(0.2, s_end - s_start)
                c_p = audio_clips_path.get(seg["id"])
                a_dur = v_dur
                if c_p:
                    try:
                        c_temp = AudioSegment.from_file(c_p)
                        a_dur = len(c_temp) / 1000.0
                    except Exception: pass
                if a_dur > v_dur:
                    mult = a_dur / v_dur
                    out_dur = a_dur
                else:
                    mult = 1.0
                    out_dur = v_dur

                intervals.append({"t0": s_start, "t1": s_end, "mult": mult, "out_dur": out_dur})
                new_s = dict(seg)
                new_s["start"] = round(new_timeline, 2)
                new_s["end"] = round(new_timeline + out_dur, 2)
                new_segments.append(new_s)
                new_timeline += out_dur
                cur_orig = s_end

            if total_dur > cur_orig:
                gap_dur = total_dur - cur_orig
                intervals.append({"t0": cur_orig, "t1": total_dur, "mult": 1.0, "out_dur": gap_dur})
                new_timeline += gap_dur

            need_retime = any(abs(it["mult"] - 1.0) > 0.02 for it in intervals)
            if need_retime and len(intervals) > 0 and len(intervals) <= 150:
                report_progress(76, "Đang co giãn Video theo nhịp câu nói (giữ giọng 1.0x)...", force=True)
                retime_script = os.path.join(work_dir, "retime_filter.txt")
                N = len(intervals)
                splits = ''.join(f'[v{i}]' for i in range(N))
                f_lines = [f'[0:v]split={N}{splits}']
                parts = []
                for i, it in enumerate(intervals):
                    t0, t1, mult = it["t0"], it["t1"], it["mult"]
                    if abs(mult - 1.0) < 0.02:
                        f_lines.append(f'[v{i}]trim={t0:.3f}:{t1:.3f},setpts=PTS-STARTPTS[p{i}]')
                    else:
                        f_lines.append(f'[v{i}]trim={t0:.3f}:{t1:.3f},setpts={mult:.4f}*(PTS-STARTPTS)[p{i}]')
                    parts.append(f'[p{i}]')
                joined_p = ''.join(parts)
                f_lines.append(f'{joined_p}concat=n={N}:v=1:a=0[outv_retime]')
                with open(retime_script, "w", encoding="utf-8") as rf:
                    rf.write(";\n".join(f_lines))

                retimed_mp4 = os.path.join(work_dir, "retimed_video.mp4")
                cmd_ret = ["ffmpeg", "-y", "-i", "input_video.mp4", "-filter_complex_script", "retime_filter.txt", "-map", "[outv_retime]", "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "retimed_video.mp4"]
                p_ret = subprocess.run(cmd_ret, cwd=work_dir, capture_output=True, text=True)
                if p_ret.returncode == 0 and os.path.exists(retimed_mp4) and os.path.getsize(retimed_mp4) > 1000:
                    video_input_name = "retimed_video.mp4"
                    vid_w, vid_h, total_dur, _ = probe_video_info(retimed_mp4)
                    segments = new_segments

            synced_items = []
            for seg in segments:
                c_p = audio_clips_path.get(seg["id"])
                if c_p:
                    synced_items.append((float(seg["start"]), c_p))

        # CHẾ ĐỘ 2: CO GIÃN GIỌNG ĐỌC ATEMPO (GIỮ NGUYÊN VIDEO - CHUẨN XÁC, SIÊU TỐC)
        else:
            report_progress(72, "Đang đồng bộ tốc độ âm thanh khớp Timeline trên Cloud...", force=True)
            done_sync = 0
            total_sync = len(segments)
            sync_lock = threading.Lock()

            def sync_one(seg):
                nonlocal done_sync
                c_path = os.path.join(tts_dir, f"s_{seg['id']}.wav")
                if not os.path.exists(c_path):
                    c_path = os.path.join(tts_dir, f"s_{seg['id']}.mp3")
                if not os.path.exists(c_path):
                    with sync_lock:
                        done_sync += 1
                    return None
                s_sec, e_sec = float(seg["start"]), float(seg["end"])
                t_dur = max(0.3, e_sec - s_sec)
                final_path = c_path
                try:
                    clip = AudioSegment.from_file(c_path)
                    c_dur = len(clip) / 1000.0
                    if c_dur > t_dur:
                        ratio = min(1.85, c_dur / t_dur)
                        f_path = os.path.join(tts_dir, f"f_{seg['id']}.wav")
                        subprocess.run(["ffmpeg", "-y", "-i", c_path, "-filter:a", f"atempo={ratio:.3f}", f_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                        if os.path.exists(f_path) and os.path.getsize(f_path) > 100:
                            final_path = f_path
                except Exception: pass

                with sync_lock:
                    done_sync += 1
                    if done_sync % 100 == 0 or done_sync == total_sync:
                        p_val = 72 + int((done_sync / max(1, total_sync)) * 5)
                        report_progress(p_val, f"Đang đồng bộ âm thanh ({done_sync}/{total_sync} câu)...")
                return (s_sec, final_path)

            synced_items = []
            with ThreadPoolExecutor(max_workers=16) as ex:
                for res in ex.map(sync_one, segments):
                    if res: synced_items.append(res)

        # TRỘN ÂM THANH SIÊU TỐC BẰNG NUMPY HIGH-SPEED BUFFER + FFMPEG AMIX (CHỐNG TRÀN RAM & DISK)
        report_progress(77, "Đang hòa trộn dải âm thanh lồng tiếng siêu tốc (Numpy High-Speed Mixer)...", force=True)
        SR = 24000
        max_end_time = max((s[0] + 5.0 for s in synced_items), default=total_dur + 5.0)
        total_audio_sec = max(total_dur + 5.0, max_end_time)
        total_samples = int(total_audio_sec * SR) + SR * 2
        voice_track_wav = os.path.join(work_dir, "voice_track.wav")

        try:
            import numpy as np
            voice_buf = np.zeros(total_samples, dtype=np.int16)
            for s_sec, a_path in synced_items:
                try:
                    c = AudioSegment.from_file(a_path).set_frame_rate(SR).set_channels(1).set_sample_width(2)
                    c_data = np.frombuffer(c.raw_data, dtype=np.int16)
                    st_idx = int(s_sec * SR)
                    en_idx = min(st_idx + len(c_data), total_samples)
                    if en_idx > st_idx:
                        voice_buf[st_idx:en_idx] = np.clip(
                            voice_buf[st_idx:en_idx].astype(np.int32) + c_data[:en_idx - st_idx],
                            -32768, 32767
                        ).astype(np.int16)
                except Exception: pass

            with wave.open(voice_track_wav, "wb") as wf:
                wf.setnchannels(1)
                wf.setsampwidth(2)
                wf.setframerate(SR)
                wf.writeframes(voice_buf.tobytes())
            del voice_buf
            print(f"[MIXER] Trộn thành công {len(synced_items)} câu vào timeline trong 0.8s!", flush=True)
        except Exception as e_mix:
            print(f"[!] Fallback tạo voice_track bằng pydub: {e_mix}", flush=True)
            try:
                master_a = AudioSegment.silent(duration=int((total_dur + 5) * 1000))
                for s_sec, a_path in synced_items:
                    try:
                        c = AudioSegment.from_file(a_path)
                        master_a = master_a.overlay(c, position=int(s_sec * 1000))
                    except Exception: pass
                master_a.export(voice_track_wav, format="wav")
                del master_a
            except Exception: pass

        if not os.path.exists(voice_track_wav):
            subprocess.run(["ffmpeg", "-y", "-f", "lavfi", "-i", "anullsrc=r=24000:cl=mono", "-t", f"{int(total_dur)+2}", voice_track_wav], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

        if has_audio and orig_vol > 0.01:
            report_progress(78, "Đang hòa trộn giọng đọc AI và âm nền video gốc (FFmpeg Native amix)...", force=True)
            amix_cmd = [
                "ffmpeg", "-y", "-i", video_path, "-i", voice_track_wav,
                "-filter_complex", f"[0:a]volume={orig_vol:.3f}[a0];[1:a]volume=1.0[a1];[a0][a1]amix=inputs=2:duration=first:dropout_transition=2[aout]",
                "-map", "[aout]", "-c:a", "pcm_s16le", final_audio
            ]
            p_mix = subprocess.run(amix_cmd, capture_output=True, text=True)
            if p_mix.returncode != 0 or not os.path.exists(final_audio) or os.path.getsize(final_audio) < 1000:
                shutil.copyfile(voice_track_wav, final_audio)
        else:
            shutil.copyfile(voice_track_wav, final_audio)

        # GIẢI PHÓNG DISK: Dọn dẹp sạch toàn bộ file tạm TTS để giải phóng dung lượng đĩa runner (~2GB)
        try:
            shutil.rmtree(tts_dir, ignore_errors=True)
            if os.path.exists(voice_track_wav):
                os.remove(voice_track_wav)
            print("[CLEANUP] Đã dọn sạch tts_dir, giải phóng đĩa thành công!", flush=True)
        except Exception: pass

    # BƯỚC 4: RENDER VIDEO TRÊN CLOUD (KÈM SMARTBLUR + CHỮ MỜ DVD + LOGO)
    srt_path = os.path.join(work_dir, "sub_vi.srt")
    with open(srt_path, "w", encoding="utf-8") as f:
        for i, s in enumerate(segments, 1):
            f.write(f"{i}\n{format_srt_time(s['start'])} --> {format_srt_time(s['end'])}\n{(s.get('trans') or s.get('text') or '').strip()}\n\n")

    ass_path = os.path.join(work_dir, "sub_vi.ass")
    generate_ass(ass_path, segments, vid_w, vid_h, st, addon_cfg, total_dur)
    out_video = os.path.join(work_dir, "output_vietsub.mp4")

    render_mode = st.get("renderMode", "hybrid_gpu")
    if render_mode == "copy":
        report_progress(85, "Đang đóng gói Stream Copy trên Cloud...", force=True)
        cmd = ["ffmpeg", "-y", "-i", video_input_name, "-i", "mixed_audio.wav", "-i", "sub_vi.srt", "-map", "0:v:0", "-map", "1:a:0", "-map", "2:s:0", "-c:v", "copy", "-c:a", "aac", "-b:a", "192k", "-c:s", "mov_text", "-movflags", "+faststart", "output_vietsub.mp4"]
        subprocess.run(cmd, cwd=work_dir, check=True)
    else:
        test_nvenc = subprocess.run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-f", "lavfi", "-i", "color=c=black:s=128x128:d=0.1", "-c:v", "h264_nvenc", "-f", "null", "-"], capture_output=True)
        use_nvenc = (test_nvenc.returncode == 0)
        enc_label = "GPU T4 NVENC" if use_nvenc else "Cloud Multi-Core CPU (Tốc độ cao)"
        report_progress(80, f"Đang Render Video bằng {enc_label} ({vid_w}x{vid_h})...", force=True)

        # Multi-area Blur & SmartBlur sâu tự nhiên
        raw_areas = st.get("blurAreas") or []
        if not raw_areas and st.get("blurRect"):
            raw_areas = [st.get("blurRect")]

        valid_areas = []
        for rect in raw_areas:
            try:
                rx = int(rect.get("x", 0))
                ry = int(rect.get("y", 0))
                rw = int(rect.get("w", 0))
                rh = int(rect.get("h", 0))
            except Exception:
                continue
            if rw < 8 or rh < 8:
                continue
            bx = max(0, rx // 2 * 2)
            by = max(0, ry // 2 * 2)
            if vid_w and vid_h:
                if bx >= vid_w - 8 or by >= vid_h - 8:
                    continue
                bw = min(rw // 2 * 2, (vid_w - bx) // 2 * 2)
                bh = min(rh // 2 * 2, (vid_h - by) // 2 * 2)
            else:
                bw = rw // 2 * 2
                bh = rh // 2 * 2
            if bw >= 8 and bh >= 8:
                valid_areas.append({"x": bx, "y": by, "w": bw, "h": bh})

        # NẾU CHƯA CÓ VÙNG CHE MỜ: TỰ ĐỘNG QUÉT VỊ TRÍ PHỤ ĐỀ HOẶC CHE DẢI ĐÁY TIÊU CHUẨN
        if len(valid_areas) == 0:
            report_progress(78, "🔍 SmartBlur: Đang tự động quét vị trí dòng phụ đề gốc...")
            detected = detect_sub_blur_area(video_input_name, vid_w, vid_h)
            valid_areas.append(detected)
            print(f"[*] SmartBlur auto-detected region: {detected}", flush=True)

        b_op = float(st.get("blurOpacity", 0)) / 100.0
        b_sig = int(st.get("blurSigma", 24))
        eff_sig = max(10, b_sig if b_sig > 0 else 24)
        b_col = st.get("blurColor", "#000000").lstrip('#')

        def build_blur_box(a):
            aw, ah = a['w'], a['h']
            safe_r = min(40, max(16, int(ah * 0.45)))
            safe_r = min(safe_r, max(2, ah // 2 - 1))
            steps = [f"crop={aw}:{ah}:{a['x']}:{a['y']}"]
            steps.append(f"boxblur=luma_radius={safe_r}:luma_power=3:chroma_radius={safe_r}")
            # Lớp kính đen mờ quang học 32% xóa sạch triệt để chữ gốc tiếng Trung
            eff_opacity = max(b_op, 0.32) if b_op <= 0.05 else b_op
            steps.append(f"drawbox=x=0:y=0:w={aw}:h={ah}:color=0x{b_col}@{eff_opacity:.2f}:t=fill")
            return ",".join(steps)

        if len(valid_areas) == 0:
            base_vf = "[0:v]ass='sub_vi.ass'[v_sub]"
        elif len(valid_areas) == 1:
            a = valid_areas[0]
            b_chain = build_blur_box(a)
            base_vf = f"[0:v]split=2[main][cs];[cs]{b_chain}[bl];[main][bl]overlay={a['x']}:{a['y']}:shortest=1,ass='sub_vi.ass'[v_sub]"
        else:
            n_areas = len(valid_areas)
            splits = "".join([f"[cs{i}]" for i in range(n_areas)])
            parts = [f"[0:v]split={n_areas+1}[main]{splits}"]
            for i, a in enumerate(valid_areas):
                b_chain = build_blur_box(a)
                parts.append(f"[cs{i}]{b_chain}[bl{i}]")
            cur_l = "[main]"
            for i, a in enumerate(valid_areas):
                nxt_l = f"[tmp{i}]" if i < n_areas - 1 else "[v_bl]"
                parts.append(f"{cur_l}[bl{i}]overlay={a['x']}:{a['y']}:shortest=1{nxt_l}")
                cur_l = nxt_l
            parts.append(f"[v_bl]ass='sub_vi.ass'[v_sub]")
            base_vf = ";".join(parts)

        has_valid_logo = bool(addon_cfg.get("logo_enabled") and os.path.exists(logo_path))
        cmd = ["ffmpeg", "-y", "-progress", "pipe:1", "-nostats"]
        if use_nvenc: cmd += ["-hwaccel", "cuda"]
        cmd += ["-i", video_input_name]

        audio_input_idx = None
        next_idx = 1
        if enable_tts and os.path.exists(final_audio):
            cmd += ["-i", "mixed_audio.wav"]
            audio_input_idx = next_idx
            next_idx += 1

        if has_valid_logo:
            cmd += ["-i", "watermark_logo.png"]
            logo_idx = next_idx
            lw = max(32, min(400, int(addon_cfg.get("logo_scale", 110))))
            la = max(0.1, min(1.0, float(addon_cfg.get("logo_opacity", 75)) / 100.0))
            lmode = addon_cfg.get("logo_mode", "top_right")
            if lmode == "top_left": pos_e = "x=24:y=24"
            elif lmode == "bottom_left": pos_e = "x=24:y=H-h-24"
            elif lmode == "bottom_right": pos_e = "x=W-w-24:y=H-h-24"
            elif lmode == "dvd_bounce": pos_e = "x='abs(mod(t*95,2*(W-w))-(W-w))':y='abs(mod(t*65,2*(H-h))-(H-h))'"
            else: pos_e = "x=W-w-24:y=24"
            vf = f"{base_vf};[{logo_idx}:v]scale={lw}:-2,format=rgba,colorchannelmixer=aa={la:.2f}[logo_img];[v_sub][logo_img]overlay={pos_e}:shortest=1,scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p[outv]"
        else:
            vf = base_vf.replace("[v_sub]", ",scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p[outv]")

        cmd += ["-filter_complex", vf, "-map", "[outv]"]
        if audio_input_idx is not None:
            cmd += ["-map", f"{audio_input_idx}:a"]
        else:
            cmd += ["-map", "0:a?"]

        if use_nvenc:
            cmd += ["-c:v", "h264_nvenc", "-preset", "p2", "-rc", "vbr", "-cq", "22", "-pix_fmt", "yuv420p"]
        else:
            cmd += ["-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-threads", "0", "-pix_fmt", "yuv420p"]
        cmd += ["-movflags", "+faststart", "-c:a", "aac", "-b:a", "192k", "output_vietsub.mp4"]

        proc = subprocess.Popen(cmd, cwd=work_dir, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, errors="ignore")
        ffmpeg_log_tail = []
        last_rep_t = 0.0
        last_rep_pct = -1
        for line in proc.stdout:
            ffmpeg_log_tail.append(line)
            if len(ffmpeg_log_tail) > 60:
                ffmpeg_log_tail.pop(0)
            if line.startswith("out_time_us="):
                try:
                    sec = int(line.strip().split("=")[1]) / 1_000_000.0
                    if total_dur > 0:
                        rp = min(99, int((sec / total_dur) * 100))
                        pct_now = 80 + int(rp * 0.14)
                        now_t = time.time()
                        if (now_t - last_rep_t >= 3.0 or rp >= 98) and pct_now > last_rep_pct:
                            last_rep_t = now_t
                            last_rep_pct = pct_now
                            report_progress(pct_now, f"Đang Render trên {enc_label} ({rp}%)...")
                except Exception: pass
        proc.wait()

        # NẾU CÓ LỖI: TỰ ĐỘNG KÍCH HOẠT FALLBACK SIÊU ỔN ĐỊNH VỚI SRT
        if proc.returncode != 0 or not os.path.exists(out_video) or os.path.getsize(out_video) < 1000:
            err_details = "".join(ffmpeg_log_tail[-25:]).strip()
            print(f"[!] FFmpeg render ban đầu cảnh báo (code {proc.returncode}):\n{err_details}", flush=True)
            report_progress(82, "FFmpeg bộ lọc nâng cao cảnh báo. Tự động kích hoạt Fallback Siêu Ổn Định...")

            fb_cmd = ["ffmpeg", "-y", "-i", video_input_name]
            fb_a_idx = None
            if enable_tts and os.path.exists(final_audio):
                fb_cmd += ["-i", "mixed_audio.wav"]
                fb_a_idx = 1

            if len(valid_areas) > 0:
                a = valid_areas[0]
                b_chain = build_blur_box(a)
                fb_vf = f"[0:v]split=2[fb_m][fb_cs];[fb_cs]{b_chain}[fb_bl];[fb_m][fb_bl]overlay={a['x']}:{a['y']}:shortest=1,subtitles='sub_vi.srt',scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p[outv]"
                fb_cmd += ["-filter_complex", fb_vf, "-map", "[outv]"]
            else:
                fb_vf = "scale=trunc(iw/2)*2:trunc(ih/2)*2,subtitles='sub_vi.srt',format=yuv420p"
                fb_cmd += ["-vf", fb_vf, "-map", "0:v:0"]

            fb_cmd += [
                "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-threads", "0",
                "-movflags", "+faststart", "-c:a", "aac", "-b:a", "192k"
            ]
            if fb_a_idx is not None:
                fb_cmd += ["-map", f"{fb_a_idx}:a:0"]
            else:
                fb_cmd += ["-map", "0:a?"]

            fb_cmd.append("output_vietsub.mp4")
            fb_proc = subprocess.run(fb_cmd, cwd=work_dir, capture_output=True, text=True, errors="ignore")
            if fb_proc.returncode != 0 or not os.path.exists(out_video) or os.path.getsize(out_video) < 1000:
                last_fb_err = (fb_proc.stderr or "")[-300:].strip()
                print(f"[!] Fallback 1 lỗi: {last_fb_err}. Thực hiện cấp cứu Stream Copy...", flush=True)
                report_progress(84, "Đang đóng gói khẩn cấp Video thành phẩm...")
                em_cmd = ["ffmpeg", "-y", "-i", video_input_name]
                if enable_tts and os.path.exists(final_audio):
                    em_cmd += ["-i", "mixed_audio.wav", "-map", "0:v:0", "-map", "1:a:0"]
                else:
                    em_cmd += ["-map", "0:v:0", "-map", "0:a?"]
                em_cmd += ["-i", "sub_vi.srt", "-map", "2:s:0", "-c:v", "copy", "-c:a", "aac", "-c:s", "mov_text", "-movflags", "+faststart", "output_vietsub.mp4"]
                em_proc = subprocess.run(em_cmd, cwd=work_dir, capture_output=True, text=True, errors="ignore")
                if em_proc.returncode != 0 or not os.path.exists(out_video) or os.path.getsize(out_video) < 1000:
                    raise RuntimeError(f"FFmpeg render thất bại với mã lỗi {proc.returncode}!\nChi tiết lỗi FFmpeg:\n{err_details[:400]}")

    # BƯỚC 5: LƯU TRỮ TRUNG GIAN TỐC ĐỘ CAO (GOFILE.IO & LITTERBOX TRỰC TIẾP) & GỬI VỀ TRẠM
    gofile_url = ""
    try:
        report_progress(91, "Đang tải bản sao lưu Video tốc độ cao lên GoFile.io...", force=True)
        r_srv = requests.get('https://api.gofile.io/servers', timeout=15)
        if r_srv.status_code == 200:
            srv = r_srv.json().get('data', {}).get('servers', [{}])[0].get('name')
            if srv:
                with open(out_video, 'rb') as f_gf:
                    r_up = requests.post(
                        f'https://{srv}.gofile.io/contents/uploadfile',
                        files={'file': ('output_vietsub.mp4', f_gf)},
                        timeout=360
                    )
                if r_up.status_code == 200:
                    d = r_up.json().get('data', {})
                    gofile_url = d.get('downloadPage') or ""
                    print(f"[*] GoFile upload OK: {gofile_url}", flush=True)
    except Exception as e_gf:
        print(f"[!] Upload GoFile notice: {e_gf}", flush=True)

    direct_url = ""
    try:
        if os.path.getsize(out_video) < 950 * 1024 * 1024:
            report_progress(93, "Đang tạo Link xem trực tiếp video trên trình duyệt...", force=True)
            headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'}
            with open(out_video, 'rb') as f_lb:
                r_lb = requests.post(
                    'https://litterbox.catbox.moe/resources/internals/api.php',
                    files={'fileToUpload': ('output_vietsub.mp4', f_lb)},
                    data={'reqtype': 'fileupload', 'time': '72h'},
                    headers=headers,
                    timeout=360
                )
            if r_lb.status_code == 200 and r_lb.text.strip().startswith('http'):
                direct_url = r_lb.text.strip()
                print(f"[*] Direct Stream URL OK: {direct_url}", flush=True)
    except Exception as e_lb:
        print(f"[!] Upload Litterbox notice: {e_lb}", flush=True)

    report_progress(95, "Đang truyền Video thành phẩm về Trạm Trung Chuyển của bạn...", force=True, gofile_url=gofile_url, direct_url=direct_url)
    video_size = os.path.getsize(out_video)
    chunk_size = 8 * 1024 * 1024  # 8MB per chunk
    total_chunks = max(1, math.ceil(video_size / chunk_size))
    seg_payload = json.dumps(segments, ensure_ascii=False)

    uploaded_ok = False
    if total_chunks > 1:
        try:
            print(f"[*] Đang tải video lên Railway dạng cắt mảnh ({total_chunks} phần, mỗi phần 8MB)...", flush=True)
            with open(out_video, "rb") as f_in:
                for c_idx in range(total_chunks):
                    chunk_bytes = f_in.read(chunk_size)
                    files = {"chunk": (f"part_{c_idx:05d}.bin", chunk_bytes, "application/octet-stream")}
                    data = {
                        "chunk_index": c_idx,
                        "total_chunks": total_chunks,
                        "gofile_url": gofile_url,
                        "direct_url": direct_url
                    }
                    if c_idx == total_chunks - 1:
                        data["segments_json"] = seg_payload
                    pct = 95 + int((c_idx / total_chunks) * 4)
                    report_progress(pct, f"Đang truyền video về Trạm ({c_idx+1}/{total_chunks} phần)...", force=True, gofile_url=gofile_url, direct_url=direct_url)
                    chunk_ok = False
                    for retry in range(4):
                        try:
                            rc = requests.post(f"{RELAY_URL}/api/relay/upload_chunk/{JOB_ID}", files=files, data=data, timeout=120)
                            if rc.status_code == 200:
                                chunk_ok = True
                                break
                            else:
                                print(f"[!] Mảnh {c_idx} lần thử {retry+1} trả về {rc.status_code}: {rc.text[:100]}", flush=True)
                        except Exception as e_c:
                            print(f"[!] Mảnh {c_idx} lần thử {retry+1} lỗi mạng: {e_c}", flush=True)
                        time.sleep(2)
                    if not chunk_ok:
                        raise RuntimeError(f"Gửi mảnh video {c_idx+1}/{total_chunks} thất bại sau 4 lần thử!")
            uploaded_ok = True
        except Exception as e_chunk:
            print(f"[!] Truyền dạng cắt mảnh gặp lỗi: {e_chunk}, chuyển sang gửi trực tiếp 1 lần...", flush=True)

    if not uploaded_ok:
        try:
            with open(out_video, "rb") as vf_file:
                files = {"video": ("output_vietsub.mp4", vf_file, "video/mp4")}
                data = {
                    "segments_json": seg_payload,
                    "gofile_url": gofile_url,
                    "direct_url": direct_url
                }
                r_up = requests.post(f"{RELAY_URL}/api/relay/upload_result/{JOB_ID}", files=files, data=data, timeout=600)
                if r_up.status_code == 200:
                    uploaded_ok = True
        except Exception as e_up:
            print(f"[!] Upload trực tiếp gặp lỗi: {e_up}", flush=True)

    report_progress(100, "🎉 Hoàn tất 100%! Đã lưu trữ Video trên GoFile & Trạm Trung Chuyển.", force=True, gofile_url=gofile_url, direct_url=direct_url)

    if GH_TOKEN and GH_CODESPACE:
        try:
            requests.post(
                f"https://api.github.com/user/codespaces/{GH_CODESPACE}/stop",
                headers={"Authorization": f"Bearer {GH_TOKEN}", "Accept": "application/vnd.github+json"},
                timeout=10
            )
        except Exception:
            pass

if __name__ == "__main__":
    try:
        run_worker()
    except Exception as e:
        import traceback
        err_detail = f"{str(e)} | {traceback.format_exc()[-400:]}"
        print(f"[!] WORKER CRITICAL ERROR: {err_detail}", flush=True)
        try:
            requests.post(f"{RELAY_URL}/api/relay/fail/{JOB_ID}", json={"error": err_detail}, timeout=15)
        except Exception:
            pass
        sys.exit(1)
    sys.exit(0)
'''

# ==================== MODULE 8: BỘ ĐIỀU PHỐI KAGGLE T4 x2 & GITHUB VPS 6H ====================
def build_worker_script_for_job(job_id, cfg, relay_url=None):
    if not relay_url:
        relay_url = get_public_relay_url()
    if not relay_url:
        relay_url = TUNNEL_INFO.get("public_url") or "http://127.0.0.1:5000"
    script = CLOUD_WORKER_SCRIPT_TEMPLATE.replace("__RELAY_URL__", relay_url)
    script = script.replace("__JOB_ID__", job_id)
    script = script.replace("__GH_TOKEN__", cfg.get("github_token", ""))
    script = script.replace("__GH_CODESPACE__", cfg.get("github_codespace_name", ""))
    return script

def dispatch_kaggle_t4_worker(job_id, ws_id=None):
    if not ws_id:
        with SERVER_JOBS_LOCK:
            if job_id in ACTIVE_SERVER_JOBS:
                ws_id = ACTIVE_SERVER_JOBS[job_id].get("workspace_id")
    if not ws_id:
        ws_id = ACTIVE_CLOUD_JOB.get("workspace_id")
    if not ws_id:
        try:
            from flask import request as flask_req
            ws_id = get_workspace_id(flask_req)
        except Exception:
            pass

    cfg = load_cloud_config(ws_id=ws_id)
    username = cfg.get("kaggle_username", "").strip()
    key = cfg.get("kaggle_key", "").strip()
    slug = cfg.get("kaggle_kernel_slug", "nexus-vietsub-worker").strip() or "nexus-vietsub-worker"

    # Fallback kiểm tra biến môi trường hoặc cấu hình global nếu workspace chưa lưu
    if not username or not key:
        username = os.environ.get("KAGGLE_USERNAME", "").strip()
        key = os.environ.get("KAGGLE_KEY", "").strip()

    if not username or not key:
        raise RuntimeError("Chưa cấu hình Kaggle Username & API Key! Hãy bấm nút '☁️ Cấu Hình Cloud' trên thanh công cụ để nhập thông tin.")

    # 1. Đặt biến môi trường chuẩn xác cho Kaggle API
    os.environ["KAGGLE_USERNAME"] = username
    os.environ["KAGGLE_KEY"] = key
    os.environ.pop("KAGGLE_API_TOKEN", None)

    kaggle_env = dict(os.environ)
    kaggle_env["KAGGLE_USERNAME"] = username
    kaggle_env["KAGGLE_KEY"] = key
    kaggle_env.pop("KAGGLE_API_TOKEN", None)

    # 2. Ghi file kaggle.json vào mọi thư mục cấu hình tiềm năng
    import tempfile
    target_dirs = [os.path.expanduser("~/.kaggle")]
    if os.name != "nt":
        target_dirs.extend(["/root/.kaggle", "/tmp/.kaggle", "/app/.kaggle"])
    tmp_k = os.path.join(tempfile.gettempdir(), ".kaggle")
    if tmp_k not in target_dirs:
        target_dirs.append(tmp_k)

    for k_dir in target_dirs:
        try:
            os.makedirs(k_dir, exist_ok=True)
            k_json = os.path.join(k_dir, "kaggle.json")
            with open(k_json, "w", encoding="utf-8") as f:
                json.dump({"username": username, "key": key}, f)
            if os.name != "nt":
                try: os.chmod(k_json, 0o600)
                except Exception: pass
            # Xóa sạch access_token cũ để Kaggle ưu tiên dùng API key chuẩn
            k_tok = os.path.join(k_dir, "access_token")
            if os.path.exists(k_tok):
                try: os.remove(k_tok)
                except Exception: pass
        except Exception:
            pass

    kaggle_env["KAGGLE_CONFIG_DIR"] = target_dirs[0]
    os.environ["KAGGLE_CONFIG_DIR"] = target_dirs[0]

    shutil.rmtree(KAGGLE_PUSH_DIR, ignore_errors=True)
    os.makedirs(KAGGLE_PUSH_DIR, exist_ok=True)

    worker_code = build_worker_script_for_job(job_id, cfg)
    with open(os.path.join(KAGGLE_PUSH_DIR, "worker.py"), "w", encoding="utf-8") as f:
        f.write(worker_code)

    kernel_meta = {
        "id": f"{username}/{slug}",
        "title": slug,
        "code_file": "worker.py",
        "language": "python",
        "kernel_type": "script",
        "is_private": "true",
        "enable_gpu": "true",
        "enable_internet": "true",
        "dataset_sources": [],
        "competition_sources": [],
        "kernel_sources": []
    }
    with open(os.path.join(KAGGLE_PUSH_DIR, "kernel-metadata.json"), "w", encoding="utf-8") as f:
        json.dump(kernel_meta, f, indent=2)

    update_progress(5, f"Đang khởi tạo phiên GPU T4 trên Kaggle ({username}/{slug})...")

    # 3. Kích hoạt phiên bằng Kaggle Python API trực tiếp (nạp config_values trực tiếp, không gọi authenticate() tránh bị exit(1))
    push_done = False
    last_err = ""
    try:
        from kaggle.api.kaggle_api_extended import KaggleApi
        api = KaggleApi()
        api.config_values[api.CONFIG_NAME_USER] = username
        api.config_values[api.CONFIG_NAME_KEY] = key
        api._authenticated = True
        res = api.kernels_push(KAGGLE_PUSH_DIR)
        if res and getattr(res, "error", None):
            raise RuntimeError(str(res.error))
        push_done = True
    except (Exception, SystemExit) as e_api:
        last_err = str(e_api)
        print(f"[!] Kaggle API Direct Push notice ({e_api}), fallback to subprocess...", flush=True)

    if not push_done:
        kaggle_env["KAGGLE_USERNAME"] = username
        kaggle_env["KAGGLE_KEY"] = key
        kaggle_env["KAGGLE_CONFIG_DIR"] = target_dirs[0]
        proc = subprocess.run(
            [sys.executable, "-m", "kaggle", "kernels", "push", "-p", KAGGLE_PUSH_DIR],
            capture_output=True, text=True, encoding="utf-8", errors="ignore",
            env=kaggle_env
        )
        if proc.returncode == 0:
            push_done = True
        else:
            last_err = (proc.stderr or proc.stdout or "").strip()

    if not push_done:
        if "401" in last_err or "Unauthorized" in last_err or "403" in last_err or "credentials" in last_err.lower():
            raise RuntimeError(f"Kaggle API Key hoặc Username không hợp lệ ({last_err})! Hãy kiểm tra lại trong '☁️ Cấu Hình Cloud' hoặc tải file kaggle.json mới.")
        if "phone" in last_err.lower() or "verify" in last_err.lower():
            raise RuntimeError(f"Kaggle yêu cầu xác thực số điện thoại để dùng GPU/Internet! Bạn hãy vào Kaggle.com -> Account Settings -> Phone verification để kích hoạt.")
        raise RuntimeError(f"Lỗi đẩy phiên lên Kaggle: {last_err}")

    update_progress(8, "Đã bật phiên Kaggle GPU T4! Đang chờ Kaggle tải Video từ Trạm Trung Chuyển...")

def dispatch_github_vps_worker(job_id, relay_url=None, ws_id=None):
    if not ws_id:
        with SERVER_JOBS_LOCK:
            if job_id in ACTIVE_SERVER_JOBS:
                ws_id = ACTIVE_SERVER_JOBS[job_id].get("workspace_id")
    if not ws_id:
        ws_id = ACTIVE_CLOUD_JOB.get("workspace_id")
    if not ws_id:
        try:
            from flask import request as flask_req
            ws_id = get_workspace_id(flask_req)
        except Exception:
            pass
    cfg = load_cloud_config(ws_id=ws_id)
    token = cfg.get("github_token", "").strip().strip("'\"")
    repo = cfg.get("github_repo", "").strip()

    # Tự động nạp tài khoản khả dụng từ GitHub Multi-Account Pool
    pool_acc = get_next_available_github_account()
    if pool_acc and pool_acc.get("token"):
        token = pool_acc.get("token")
        repo = pool_acc.get("repo") or repo

    if token.lower().startswith("bearer "):
        token = token[7:].strip()
    elif token.lower().startswith("token "):
        token = token[6:].strip()

    if not token or "/" not in repo:
        raise RuntimeError("Chưa cấu hình GitHub Token hoặc Repo! Hãy bấm nút '☁️ Cấu Hình Cloud' trên thanh công cụ để nhập Token mới.")

    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28"
    }

    if not relay_url or "127.0.0.1" in relay_url or "localhost" in relay_url:
        cand = get_public_relay_url()
        if cand and "127.0.0.1" not in cand and "localhost" not in cand:
            relay_url = cand
    relay_url = (relay_url or "").rstrip("/")
    if relay_url and not relay_url.startswith("http://") and not relay_url.startswith("https://"):
        relay_url = f"https://{relay_url}"

    if not relay_url:
        raise RuntimeError("Trạm Trung Chuyển chưa xác định được URL công khai! Hãy mở trang web qua link Railway .up.railway.app rồi thử lại.")

    update_progress(4, f"Đang kết nối tới GitHub VPS ({repo})...")
    r_check = requests.get(f"https://api.github.com/repos/{repo}", headers=headers, timeout=15)
    if r_check.status_code == 401:
        raise RuntimeError("GitHub Token không hợp lệ hoặc đã bị GitHub vô hiệu hóa (401 Bad credentials)! Hãy tạo Personal Access Token (Classic) mới trên GitHub với quyền 'repo' và 'workflow', sau đó dán vào '☁️ Cấu Hình Cloud' hoặc nhập vào Railway Variables (GITHUB_TOKEN).")

    if r_check.status_code == 404:
        repo_name = repo.split("/")[1]
        requests.post(
            "https://api.github.com/user/repos",
            headers=headers,
            json={"name": repo_name, "private": True, "auto_init": True},
            timeout=20
        )
        time.sleep(2)
        r_check = requests.get(f"https://api.github.com/repos/{repo}", headers=headers, timeout=15)

    default_branch = r_check.json().get("default_branch", "main") if r_check.status_code == 200 else "main"

    wf_path = ".github/workflows/nexus_worker.yml"
    wf_content = """name: Nexus Multi-Lingual 6h VPS Worker
on:
  workflow_dispatch:
    inputs:
      relay_url:
        description: 'Relay Gateway URL'
        required: true
      job_id:
        description: 'Job ID'
        required: true

jobs:
  vietsub_worker:
    runs-on: ubuntu-latest
    timeout-minutes: 360
    steps:
      - name: Set up Python 3.11
        uses: actions/setup-python@v5
        with:
          python-version: '3.11'
      - name: Install System, Fonts & AI Dependencies
        run: |
          sudo apt-get update -qq
          sudo apt-get install -y -qq ffmpeg fonts-liberation fonts-noto-core fonts-noto-cjk fontconfig
          sudo fc-cache -f
          python -m pip install -q av faster-whisper edge-tts pydub Pillow requests numpy
      - name: Run Autonomous Pipeline & Auto-Shutdown
        run: |
          echo "=========================================================="
          echo "Connecting to Nexus Relay Gateway: ${{ github.event.inputs.relay_url }}"
          echo "Job ID: ${{ github.event.inputs.job_id }}"
          echo "=========================================================="
          curl -f -sSL "${{ github.event.inputs.relay_url }}/api/relay/job/${{ github.event.inputs.job_id }}/worker.py" -o worker.py || {
            echo "Failed to download worker.py from Relay Gateway! URL: ${{ github.event.inputs.relay_url }}/api/relay/job/${{ github.event.inputs.job_id }}/worker.py"
            exit 1
          }
          if [ ! -s worker.py ]; then
            echo "Downloaded worker.py is empty (0 bytes)!"
            exit 1
          fi
          echo "worker.py downloaded successfully ($(wc -c < worker.py) bytes). Starting pipeline 24/7..."
          python -u worker.py
      - name: Archive Completed Video as GitHub Artifact
        uses: actions/upload-artifact@v4
        if: always()
        with:
          name: nexus-video-${{ github.event.inputs.job_id }}
          path: nexus_cloud_work/output_vietsub.mp4
          if-no-files-found: ignore
          retention-days: 7
"""
    wf_api_url = f"https://api.github.com/repos/{repo}/contents/{wf_path}"
    existing_wf = requests.get(wf_api_url, headers=headers, timeout=15)
    b64_wf = base64.b64encode(wf_content.encode("utf-8")).decode("utf-8")

    put_payload = {"message": "Update Nexus 6h VPS Worker", "content": b64_wf, "branch": default_branch}
    need_put = True
    if existing_wf.status_code == 200:
        ex_content = existing_wf.json().get("content", "").replace("\n", "").strip()
        if ex_content == b64_wf.replace("\n", "").strip():
            need_put = False
        else:
            put_payload["sha"] = existing_wf.json().get("sha")

    if need_put:
        requests.put(wf_api_url, headers=headers, json=put_payload, timeout=20)
        time.sleep(1.0)

    cs_name = cfg.get("github_codespace_name", "").strip()
    if cs_name:
        try:
            requests.post(f"https://api.github.com/user/codespaces/{cs_name}/start", headers=headers, timeout=15)
        except Exception:
            pass

    disp_url = f"https://api.github.com/repos/{repo}/actions/workflows/nexus_worker.yml/dispatches"
    disp_resp = requests.post(
        disp_url,
        headers=headers,
        json={"ref": default_branch, "inputs": {"relay_url": relay_url, "job_id": job_id}},
        timeout=20
    )
    if disp_resp.status_code in (401, 403):
        # Tự động chuyển tài khoản tiếp theo trong pool nếu tài khoản hiện tại hết quota 3000p hoặc bị chặn
        next_acc = get_next_available_github_account(exclude_token=token)
        if next_acc and next_acc.get("token") != token:
            print(f"[!] GitHub Account ({repo}) bị từ chối ({disp_resp.status_code}). Tự động failover sang {next_acc.get('name')} ({next_acc.get('repo')})...", flush=True)
            update_progress(5, f"Tài khoản GitHub hết hạn ngạch 3000p ➜ Đang tự động chuyển sang {next_acc.get('name')}...")
            time.sleep(1.5)
            return dispatch_github_vps_worker(job_id, relay_url=relay_url, ws_id=ws_id)
        if disp_resp.status_code == 401:
            raise RuntimeError("GitHub Token bị từ chối xác thực (401 Bad credentials)! Hãy tạo Personal Access Token mới trên GitHub và cập nhật lại.")
        else:
            raise RuntimeError("GitHub Token không đủ quyền kích hoạt GitHub Actions hoặc đã hết hạn mức 3000 phút (403 Forbidden)! Hãy thêm tài khoản dự phòng vào mục 'Quản Lý Đa Tài Khoản GitHub'.")
    elif disp_resp.status_code == 404:
        raise RuntimeError(f"Không tìm thấy file workflow nexus_worker.yml trên repo '{repo}' hoặc Actions chưa được bật! Vui lòng vào Repo Settings -> Actions -> General -> Bật 'Allow all actions and reusable workflows'.")
    elif disp_resp.status_code not in (200, 201, 204):
        raise RuntimeError(f"Lỗi kích hoạt GitHub VPS ({disp_resp.status_code}): {disp_resp.text}")

    update_progress(8, "Đã khởi tạo phiên GitHub VPS 6h! Đang chờ máy chủ nhận Video từ Trạm Trung Chuyển...")

def cancel_active_cloud_sessions():
    cfg = load_cloud_config()
    token = cfg.get("github_token", "").strip()
    repo = cfg.get("github_repo", "").strip()
    cs_name = cfg.get("github_codespace_name", "").strip()
    ACTIVE_CLOUD_JOB["status"] = "cancelled"

    if token:
        headers = {"Authorization": f"Bearer {token}", "Accept": "application/vnd.github+json"}
        if cs_name:
            try:
                requests.post(f"https://api.github.com/user/codespaces/{cs_name}/stop", headers=headers, timeout=10)
            except Exception:
                pass
        if "/" in repo:
            try:
                runs_resp = requests.get(f"https://api.github.com/repos/{repo}/actions/runs?status=in_progress", headers=headers, timeout=10)
                if runs_resp.status_code == 200:
                    for r in runs_resp.json().get("workflow_runs", []):
                        requests.post(f"https://api.github.com/repos/{repo}/actions/runs/{r['id']}/cancel", headers=headers, timeout=10)
            except Exception:
                pass

# ==================== MODULE 9: CÁC HÀM XỬ LÝ SUB, TTS & VIDEO LOCAL ====================
def sync_edge_tts_clock():
    try:
        import edge_tts.drm
        for url in ["https://www.bing.com", "https://www.google.com"]:
            try:
                resp = requests.head(url, timeout=4)
                if "Date" in resp.headers:
                    server_ts = parsedate_to_datetime(resp.headers["Date"]).timestamp()
                    skew = server_ts - time.time()
                    edge_tts.drm.DRM.clock_skew_seconds = skew
                    edge_tts.drm.DRM.get_unix_timestamp = staticmethod(lambda s=skew: time.time() + s)
                    return
            except Exception:
                continue
    except Exception:
        pass

sync_edge_tts_clock()

def get_tts_cache_key(voice, text):
    clean_text = (text or "").strip()
    raw = f"{voice}||{clean_text}"
    return hashlib.md5(raw.encode("utf-8")).hexdigest()

def has_audio_stream(video_path):
    try:
        import av
        with av.open(video_path) as container:
            return len(container.streams.audio) > 0
    except Exception:
        return True

def get_video_info(video_path):
    try:
        import av
        with av.open(video_path) as container:
            stream = container.streams.video[0]
            dur = float(container.duration / av.time_base) if container.duration else 0.0
            return stream.width, stream.height, dur
    except Exception:
        return 1280, 720, 0.0

def hex_to_ass_color(hex_color, alpha=0):
    hex_color = (hex_color or "#FFFFFF").lstrip('#')
    if len(hex_color) != 6:
        hex_color = "FFFFFF"
    r = hex_color[0:2].upper()
    g = hex_color[2:4].upper()
    b = hex_color[4:6].upper()
    return f"&H{alpha:02X}{b}{g}{r}"

def format_srt_time(seconds):
    hrs = int(seconds // 3600)
    mins = int((seconds % 3600) // 60)
    secs = int(seconds % 60)
    msecs = min(999, int(round((seconds - int(seconds)) * 1000)))
    return f"{hrs:02d}:{mins:02d}:{secs:02d},{msecs:03d}"

def format_vtt_time(seconds):
    return format_srt_time(seconds).replace(",", ".")

def format_ass_time(seconds):
    hrs = int(seconds // 3600)
    mins = int((seconds % 3600) // 60)
    secs = int(seconds % 60)
    centisecs = min(99, int(round((seconds - int(seconds)) * 100)))
    return f"{hrs:d}:{mins:02d}:{secs:02d}.{centisecs:02d}"

def generate_vtt_file(vtt_path, segments):
    with open(vtt_path, "w", encoding="utf-8") as f:
        f.write("WEBVTT\n\n")
        for idx, seg in enumerate(segments, start=1):
            line_text = (seg.get("trans") or seg.get("text") or "").strip()
            if not line_text:
                continue
            f.write(f"{idx}\n{format_vtt_time(seg['start'])} --> {format_vtt_time(seg['end'])}\n{line_text}\n\n")

def generate_ass_file(ass_path, segments, vid_w, vid_h, font_name, font_size, text_color, outline_color, outline_width, margin_v, target_lang="vi", **kwargs):
    play_res_y = 720
    play_res_x = int(round(720 * (vid_w / max(1, vid_h))))
    ass_primary = hex_to_ass_color(text_color, 0)
    ass_outline = hex_to_ass_color(outline_color, 0)
    ass_font_size = int(round(font_size * 1.28))

    if target_lang in ("zh", "ja", "ko") and font_name in ("Tahoma", "Impact", "Courier New"):
        font_name = "Arial"

    border_style = 1
    outline_val = outline_width
    back_colour = "&H80000000"

    header = f"""[Script Info]
Title: Nexus Multi-Lingual Studio
ScriptType: v4.00+
WrapStyle: 0
ScaledBorderAndShadow: yes
YCbCr Matrix: TV.709
PlayResX: {play_res_x}
PlayResY: {play_res_y}

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,{font_name},{ass_font_size},{ass_primary},&H000000FF,{ass_outline},{back_colour},-1,0,0,0,100,100,0,0,{border_style},{outline_val},0,2,25,25,{margin_v},1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
"""
    with open(ass_path, "w", encoding="utf-8") as f:
        f.write(header)
        for seg in segments:
            line_text = (seg.get("trans") or seg.get("text") or "").strip()
            if not line_text:
                continue
            clean_line = line_text.replace("\n", "\\N")
            f.write(f"Dialogue: 0,{format_ass_time(seg['start'])},{format_ass_time(seg['end'])},Default,,0,0,0,,{clean_line}\n")

def parse_srt_time(time_str):
    time_str = time_str.strip().replace('.', ',')
    parts = re.split('[:,]', time_str)
    return int(parts[0])*3600 + int(parts[1])*60 + int(parts[2]) + int(parts[3])/1000.0

def parse_srt_content(content):
    segments = []
    blocks = re.split(r'\n\s*\n', content.strip())
    idx = 1
    for block in blocks:
        lines = [l.strip() for l in block.strip().split('\n') if l.strip()]
        if len(lines) >= 2:
            time_line = lines[1] if '-->' in lines[1] else (lines[0] if '-->' in lines[0] else None)
            if not time_line:
                continue
            start_str, end_str = [t.strip() for t in time_line.split('-->')]
            text_lines = lines[2:] if time_line == lines[1] else lines[1:]
            segments.append({
                "id": idx,
                "start": round(parse_srt_time(start_str), 2),
                "end": round(parse_srt_time(end_str), 2),
                "text": " ".join(text_lines),
                "trans": ""
            })
            idx += 1
    return segments

