@app.route("/api/session/reset", methods=["POST"])
def api_reset_session():
    ws_id = get_workspace_id(request)
    reset_user_workspace(ws_id)
    update_progress(0, "Đã làm mới phiên làm việc của bạn", ws_id=ws_id)
    return jsonify({"status": "ok", "workspace": ws_id})

@app.route("/api/projects/list")
def api_list_projects():
    projects = []
    ws_dir = get_workspace_dir(request)
    scan_dirs = [os.path.join(ws_dir, "projects"), PROJECTS_DIR]
    seen_ids = set()

    for p_root in scan_dirs:
        if os.path.exists(p_root):
            for folder in os.listdir(p_root):
                if folder in seen_ids:
                    continue
                p_dir = os.path.join(p_root, folder)
                meta_file = os.path.join(p_dir, "project.json")
                if os.path.isdir(p_dir) and os.path.exists(meta_file):
                    try:
                        with open(meta_file, "r", encoding="utf-8") as f:
                            data = json.load(f)
                        projects.append({
                            "id": folder,
                            "name": data.get("name", folder),
                            "updated_at": data.get("updated_at", ""),
                            "sub_count": len(data.get("segments", [])),
                            "has_video": os.path.exists(os.path.join(p_dir, "video.mp4"))
                        })
                        seen_ids.add(folder)
                    except Exception:
                        continue
    projects.sort(key=lambda x: x["updated_at"], reverse=True)
    return jsonify({"projects": projects})

@app.route("/api/projects/save", methods=["POST"])
def api_save_project():
    data = request.json or {}
    pid = data.get("project_id") or datetime.now().strftime("proj_%Y%m%d_%H%M%S_") + uuid.uuid4().hex[:4]
    name = data.get("name", "Dự án chưa đặt tên")
    segments = data.get("segments", [])
    settings = data.get("settings", {})

    ws_dir = get_workspace_dir(request)
    p_dir = os.path.join(ws_dir, "projects", pid)
    os.makedirs(p_dir, exist_ok=True)

    temp_video = os.path.join(ws_dir, "input_video.mp4")
    if not os.path.exists(temp_video):
        temp_video = os.path.join(TEMP_DIR, "input_video.mp4")

    proj_video = os.path.join(p_dir, "video.mp4")
    if os.path.exists(temp_video):
        if not os.path.exists(proj_video) or os.path.getsize(temp_video) != os.path.getsize(proj_video):
            shutil.copy2(temp_video, proj_video)

    meta = {
        "project_id": pid,
        "name": name,
        "updated_at": datetime.now().strftime("%d/%m/%Y %H:%M"),
        "segments": segments,
        "settings": settings
    }
    with open(os.path.join(p_dir, "project.json"), "w", encoding="utf-8") as f:
        json.dump(meta, f, ensure_ascii=False, indent=2)

    return jsonify({"status": "ok", "project_id": pid, "name": name})

@app.route("/api/projects/load/<pid>", methods=["POST"])
def api_load_project(pid):
    ws_dir = get_workspace_dir(request)
    p_dir = os.path.join(ws_dir, "projects", pid)
    meta_file = os.path.join(p_dir, "project.json")
    if not os.path.exists(meta_file):
        p_dir = os.path.join(PROJECTS_DIR, pid)
        meta_file = os.path.join(p_dir, "project.json")
    if not os.path.exists(meta_file):
        return jsonify({"error": "Không tìm thấy dự án này!"}), 404

    reset_user_workspace(get_workspace_id(request))
    with open(meta_file, "r", encoding="utf-8") as f:
        meta = json.load(f)

    proj_video = os.path.join(p_dir, "video.mp4")
    ws_video = os.path.join(ws_dir, "input_video.mp4")
    temp_video = os.path.join(TEMP_DIR, "input_video.mp4")
    has_video = False
    if os.path.exists(proj_video):
        shutil.copy2(proj_video, ws_video)
        shutil.copy2(proj_video, temp_video)
        has_video = True

    return jsonify({
        "status": "ok",
        "project_id": pid,
        "name": meta.get("name", pid),
        "segments": meta.get("segments", []),
        "settings": meta.get("settings", {}),
        "has_video": has_video
    })

@app.route("/api/projects/delete/<pid>", methods=["DELETE"])
def api_delete_project(pid):
    p_dir = os.path.join(PROJECTS_DIR, pid)
    if os.path.exists(p_dir):
        shutil.rmtree(p_dir, ignore_errors=True)
    return jsonify({"status": "ok"})

@app.route("/api/export_srt", methods=["POST"])
def api_export_srt():
    data = request.json
    segments = data.get("segments", [])
    mode = data.get("mode", "vi")

    srt_filename = f"export_{mode}.srt"
    srt_path = os.path.join(TEMP_DIR, srt_filename)
    with open(srt_path, "w", encoding="utf-8") as f:
        for idx, seg in enumerate(segments, start=1):
            orig_txt = (seg.get("text") or "").strip()
            trans_txt = (seg.get("trans") or "").strip()
            if mode == "orig":
                line_text = orig_txt or trans_txt
            elif mode == "bi":
                line_text = f"{orig_txt}\n{trans_txt}" if (orig_txt and trans_txt) else (trans_txt or orig_txt)
            else:
                line_text = trans_txt or orig_txt
            f.write(f"{idx}\n{format_srt_time(seg['start'])} --> {format_srt_time(seg['end'])}\n{line_text}\n\n")
    return send_from_directory(TEMP_DIR, srt_filename, as_attachment=True)

@app.route("/upload_video", methods=["POST"])
def upload_video():
    file = request.files.get("video")
    if not file:
        return jsonify({"error": "Không tìm thấy file video"}), 400
    ws_id = get_workspace_id(request)
    ws_dir = get_workspace_dir(request)
    os.makedirs(ws_dir, exist_ok=True)
    video_path = os.path.join(ws_dir, "input_video.mp4")
    file.save(video_path)
    # Lưu bản sao sang TEMP_DIR làm dự phòng toàn cục
    try:
        shutil.copy2(video_path, os.path.join(TEMP_DIR, "input_video.mp4"))
    except Exception:
        pass
    LAST_AUDIO_SIGNATURE["sig"] = None
    audio_ok = has_audio_stream(video_path)
    return jsonify({"status": "ok", "video_url": f"/workspace/{ws_id}/input_video.mp4?t={int(time.time())}", "has_audio": audio_ok, "workspace": ws_id})

@app.route("/api/video/download_url", methods=["POST"])
def api_download_video_from_url():
    """Tự động tải video từ YouTube, Bilibili, Douyin, TikTok... về workspace và nạp thẳng vào tool"""
    data = request.json or {}
    raw_url = (data.get("url") or "").strip()
    if not raw_url:
        return jsonify({"ok": False, "error": "Vui lòng nhập đường dẫn (link) video!"}), 400

    # 1. Trích xuất URL sạch nếu người dùng dán kèm văn bản chia sẻ từ app (Douyin, TikTok, Facebook)
    url_match = re.search(r'https?://[^\s<>"\']+', raw_url)
    if url_match:
        url = url_match.group(0)
    elif re.match(r'^(BV|bv)[0-9a-zA-Z]{10}$', raw_url):
        url = f"https://www.bilibili.com/video/{raw_url}"
    else:
        url = raw_url

    # 2. Chuẩn hóa link Bilibili: loại bỏ các tiền tố dịch tự động của trình duyệt như /vi/, /en/
    url = re.sub(r'bilibili\.com/[a-zA-Z]{2}(-[a-zA-Z]{2})?/video/', 'bilibili.com/video/', url)

    # 3. Kích hoạt ffmpeg vào PATH nếu có static_ffmpeg
    try:
        import static_ffmpeg
        static_ffmpeg.add_paths()
    except Exception:
        pass

    ws_id = get_workspace_id(request)
    ws_dir = get_workspace_dir(request)
    os.makedirs(ws_dir, exist_ok=True)
    video_path = os.path.join(ws_dir, "input_video.mp4")

    # Xóa file cũ
    for fp in [video_path, os.path.join(TEMP_DIR, "input_video.mp4")]:
        if os.path.exists(fp):
            try: os.remove(fp)
            except Exception: pass

    try:
        try:
            import yt_dlp
        except ModuleNotFoundError:
            # Tự động cài đặt nóng yt-dlp tại runtime nếu môi trường Railway/VPS chưa kịp build
            import sys
            try:
                subprocess.run([sys.executable, "-m", "pip", "install", "yt-dlp", "--no-cache-dir"], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                import yt_dlp
            except Exception as pe:
                return jsonify({"ok": False, "error": f"Máy chủ Railway chưa có thư viện 'yt-dlp' và không thể tự cài ({pe}). Vui lòng thêm dòng 'yt-dlp>=2024.0.0' vào file requirements.txt trên GitHub Railway rồi bấm Redeploy!"}), 500

        target_template = os.path.join(ws_dir, "dl_temp.%(ext)s")
        is_bili = any(x in url.lower() for x in ['bilibili.com', 'b23.tv'])
        req_headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36',
            'Accept': '*/*',
            'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8,vi;q=0.7'
        }
        if is_bili:
            req_headers['Referer'] = 'https://www.bilibili.com/'
            # Header Range: bytes=0- là BẮT BUỘC để vượt qua tường lửa Tencent CDN (chống lỗi HTTP Error 567)
            req_headers['Range'] = 'bytes=0-'
        else:
            req_headers['Referer'] = 'https://www.google.com/'

        ydl_opts = {
            'format': 'bestvideo+bestaudio/best',
            'outtmpl': target_template,
            'merge_output_format': 'mp4',
            'overwrites': True,
            'quiet': True,
            'no_warnings': True,
            'nocheckcertificate': True,
            'retries': 10,
            'fragment_retries': 10,
            'http_headers': req_headers
        }
        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
            info = ydl.extract_info(url, download=True)
            video_title = info.get("title") or "Video từ Link"
            duration = info.get("duration") or 0

        downloaded_file = None
        for cand in os.listdir(ws_dir):
            if cand.startswith("dl_temp."):
                downloaded_file = os.path.join(ws_dir, cand)
                break

        if not downloaded_file or not os.path.exists(downloaded_file):
            return jsonify({"ok": False, "error": "Không thể tải video từ link này. Vui lòng kiểm tra lại đường dẫn!"}), 400

        if downloaded_file.endswith(".mp4"):
            shutil.move(downloaded_file, video_path)
        else:
            subprocess.run(["ffmpeg", "-y", "-i", downloaded_file, "-c", "copy", video_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if not os.path.exists(video_path) or os.path.getsize(video_path) < 100:
                subprocess.run(["ffmpeg", "-y", "-i", downloaded_file, "-c:v", "libx264", "-c:a", "aac", video_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            try: os.remove(downloaded_file)
            except Exception: pass

        if not os.path.exists(video_path) or os.path.getsize(video_path) < 100:
            return jsonify({"ok": False, "error": "Lỗi định dạng video sau khi tải về!"}), 500

        try:
            shutil.copy2(video_path, os.path.join(TEMP_DIR, "input_video.mp4"))
        except Exception:
            pass

        LAST_AUDIO_SIGNATURE["sig"] = None
        audio_ok = has_audio_stream(video_path)
        return jsonify({
            "ok": True,
            "title": video_title,
            "duration": duration,
            "video_url": f"/workspace/{ws_id}/input_video.mp4?t={int(time.time())}",
            "has_audio": audio_ok
        })
    except Exception as e:
        err_msg = str(e)
        if "is unusual and will be skipped" in err_msg or "HTTP Error 404" in err_msg:
            err_msg = "Không tìm thấy video từ link này (Lỗi 404 hoặc link sai). Với Bilibili, mã BV chuẩn gồm 12 ký tự (Ví dụ: BV1atse6EEfx), bạn vui lòng kiểm tra lại link gốc xem có bị thiếu ký tự không nhé!"
        return jsonify({"ok": False, "error": f"Lỗi tải video: {err_msg}"}), 500

@app.route("/merge_audio", methods=["POST"])
def merge_audio():
    ws_dir = get_workspace_dir(request)
    video_path = os.path.join(ws_dir, "input_video.mp4")
    if not os.path.exists(video_path):
        video_path = os.path.join(TEMP_DIR, "input_video.mp4")
    if not os.path.exists(video_path):
        return jsonify({"error": "Vui lòng chọn file Video trước khi ghép Audio!"}), 400

    file = request.files.get("audio")
    if not file:
        return jsonify({"error": "Không tìm thấy file audio"}), 400

    ext = os.path.splitext(file.filename)[1] or ".m4a"
    audio_path = os.path.join(ws_dir, f"raw_audio{ext}")
    merged_path = os.path.join(ws_dir, "merged_temp.mp4")
    file.save(audio_path)

    cmd = [
        "ffmpeg", "-y", "-i", video_path, "-i", audio_path,
        "-c:v", "copy", "-c:a", "aac", "-map", "0:v:0", "-map", "1:a:0",
        "-shortest", "-movflags", "+faststart", merged_path
    ]
    proc = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="ignore")
    if proc.returncode != 0:
        return jsonify({"error": f"Không thể ghép Audio: {proc.stderr[-300:]}"}), 500

    os.replace(merged_path, video_path)
    try:
        shutil.copy2(video_path, os.path.join(TEMP_DIR, "input_video.mp4"))
    except Exception:
        pass
    return jsonify({"status": "ok", "video_url": "/temp_session/input_video.mp4"})

@app.route("/upload_srt", methods=["POST"])
def upload_srt():
    file = request.files.get("srt")
    if not file:
        return jsonify({"error": "Không tìm thấy file SRT"}), 400
    content = file.read().decode("utf-8", errors="ignore")
    segments = parse_srt_content(content)
    return jsonify({"segments": segments})

def do_transcribe_core(video_path, model_size="small", device_req="auto", source_lang="auto", progress_cb=None):
    if progress_cb is None:
        progress_cb = update_progress

    from faster_whisper import WhisperModel
    progress_cb(12, f"Đang khởi tạo Whisper ({model_size}) trên máy trạm...")

    cpu_threads = max(1, min(HARDWARE_INFO.get("cpu_threads", 4), 4))
    device_mode = "cpu"
    compute_mode = "int8"
    model = None

    # Tự động ưu tiên base/tiny trên Cloud/Railway để đảm bảo không bao giờ bị OOM tràn RAM
    is_cloud_env = bool(os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("PORT"))
    if is_cloud_env and model_size == "small":
        models_to_try = ["base", "tiny", "small"]
    else:
        models_to_try = [model_size]
        for fb in ["base", "tiny"]:
            if fb not in models_to_try:
                models_to_try.append(fb)

    for m_cand in models_to_try:
        try:
            if (device_req == "cuda" or (device_req == "auto" and HARDWARE_INFO.get("cuda_available"))) and m_cand == model_size:
                try:
                    device_mode = "cuda"
                    compute_mode = "float16"
                    model = WhisperModel(m_cand, device=device_mode, compute_type=compute_mode)
                    break
                except Exception as e_cuda:
                    print(f"[!] Không thể chạy Whisper trên CUDA ({e_cuda}), tự động fallback CPU...", flush=True)
                    device_mode = "cpu"
                    compute_mode = "int8"
            
            model = WhisperModel(m_cand, device="cpu", compute_type="int8", cpu_threads=cpu_threads)
            if m_cand != model_size:
                print(f"[i] Đã tự động tối ưu hóa Model Whisper sang '{m_cand}' để đảm bảo an toàn bộ nhớ 24/7.", flush=True)
            break
        except (MemoryError, Exception) as mem_err:
            print(f"[!] Không thể nạp Whisper model '{m_cand}' ({mem_err}), đang thử model nhỏ hơn...", flush=True)
            continue

    if model is None:
        raise RuntimeError("Không đủ bộ nhớ để tải mô hình tách tiếng Whisper. Vui lòng thử lại với video ngắn hơn hoặc chọn model tiny!")

    _, _, total_dur = get_video_info(video_path)
    progress_cb(20, f"Bắt đầu tách giọng nói bằng Whisper ({device_mode.upper()})...")

    # Chuẩn hóa trích xuất âm thanh sang 16kHz mono WAV để tránh lỗi PyAV trên video quay từ điện thoại (iOS/Android)
    wav_path = os.path.join(os.path.dirname(video_path), "extracted_whisper_input.wav")
    audio_target = video_path
    try:
        cmd_wav = [
            "ffmpeg", "-y", "-i", video_path, "-vn",
            "-acodec", "pcm_s16le", "-ar", "16000", "-ac", "1",
            wav_path
        ]
        ret_wav = subprocess.run(cmd_wav, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=45)
        if ret_wav.returncode == 0 and os.path.exists(wav_path) and os.path.getsize(wav_path) > 100:
            audio_target = wav_path
    except Exception as e_wav:
        print(f"[!] Ghi chú trích xuất WAV phụ: {e_wav}", flush=True)

    transcribe_args = {"beam_size": 5}
    if source_lang and source_lang != "auto":
        transcribe_args["language"] = source_lang

    try:
        raw_segments, info = model.transcribe(audio_target, **transcribe_args)
        detected_lang = getattr(info, "language", None)

        segments = []
        for idx, seg in enumerate(raw_segments, start=1):
            segments.append({
                "id": idx,
                "start": round(seg.start, 2),
                "end": round(seg.end, 2),
                "text": seg.text.strip(),
                "trans": ""
            })
            pct = 25 + (int((seg.end / total_dur) * 72) if total_dur > 0 else min(70, idx))
            progress_cb(min(98, pct), f"Đã tách câu #{idx}: {seg.text[:28]}...")
    finally:
        if audio_target != video_path and os.path.exists(audio_target):
            try:
                os.remove(audio_target)
            except Exception:
                pass

    progress_cb(100, f"Hoàn tất tách {len(segments)} câu phụ đề!")
    return segments, detected_lang, device_mode

@app.route("/transcribe", methods=["POST"])
def transcribe_video_local():
    ws_dir = get_workspace_dir(request)
    video_path = os.path.join(ws_dir, "input_video.mp4")
    if not os.path.exists(video_path):
        video_path = os.path.join(TEMP_DIR, "input_video.mp4")
    if not os.path.exists(video_path):
        return jsonify({"error": "Vui lòng tải video lên trước!"}), 400

    data = request.json or {}
    model_size = data.get("model", "small")
    device_req = data.get("device", "auto")
    source_lang = data.get("sourceLang", "auto")

    try:
        segments, detected_lang, device_mode = do_transcribe_core(video_path, model_size, device_req, source_lang)
        return jsonify({
            "segments": segments,
            "detected_lang": detected_lang,
            "device_used": device_mode
        })
    except Exception as e:
        return jsonify({"error": f"Lỗi Whisper: {str(e)}"}), 500

# ==================== BỘ CÔNG CỤ DỊCH THUẬT ĐA ĐỘNG CƠ (GOOGLE + GEMINI HYBRID) ====================
def translate_google_batch(items, target_lang='vi', source_lang='auto'):
    """
    Dịch danh sách (id, text) qua Google Translate (Miễn phí 100%, không cần API Key).
    Xử lý theo khối 25 câu có gắn tag [[ID_x]], fallback từng câu nếu thiếu.
    """
    if not items:
        return {}
    res_map = {}
    batch_size = 25
    chunks = [items[i:i+batch_size] for i in range(0, len(items), batch_size)]
    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/120.0.0.0"}

    def _call_g_chunk(chunk):
        encoded = "\n".join([f"[[ID_{sid}]] {txt}" for sid, txt in chunk if txt.strip()])
        if not encoded.strip():
            return {}
        try:
            url = "https://translate.googleapis.com/translate_a/single"
            params = {"client": "gtx", "sl": source_lang, "tl": target_lang, "dt": "t", "q": encoded}
            r = requests.get(url, params=params, headers=headers, timeout=12)
            if r.status_code == 200:
                raw_t = "".join([p[0] for p in r.json()[0] if p and p[0]])
                matches = re.finditer(r'\[\[ID_(\d+)\]\]\s*(.*?)(?=\[\[ID_\d+\]\]|$|\n)', raw_t, re.DOTALL)
                sub_res = {}
                for m in matches:
                    sid = int(m.group(1))
                    val = m.group(2).strip()
                    if val:
                        sub_res[sid] = val
                return sub_res
        except Exception:
            pass
        return {}

    with ThreadPoolExecutor(max_workers=min(len(chunks) or 1, 8)) as ex:
        futs = [ex.submit(_call_g_chunk, ch) for ch in chunks]
        for f in as_completed(futs):
            res_map.update(f.result())

    # Fallback từng câu nếu chunk nào đó bị sót dòng
    missing = [it for it in items if it[0] not in res_map and it[1].strip()]
    if missing:
        def _call_single(it):
            sid, txt = it
            try:
                url = "https://translate.googleapis.com/translate_a/single"
                params = {"client": "gtx", "sl": source_lang, "tl": target_lang, "dt": "t", "q": txt}
                r = requests.get(url, params=params, headers=headers, timeout=6)
                if r.status_code == 200:
                    val = "".join([p[0] for p in r.json()[0] if p and p[0]]).strip()
                    return sid, val
            except Exception:
                pass
            return sid, ""

        with ThreadPoolExecutor(max_workers=min(len(missing), 6)) as ex:
            for sid, val in ex.map(_call_single, missing):
                if val:
                    res_map[sid] = val

    return res_map

def translate_single_text(text, target_lang='vi', source_lang='auto'):
    if not text or not text.strip():
        return ""
    try:
        url = "https://translate.googleapis.com/translate_a/single"
        params = {"client": "gtx", "sl": source_lang, "tl": target_lang, "dt": "t", "q": text}
        headers = {"User-Agent": "Mozilla/5.0"}
        r = requests.get(url, params=params, headers=headers, timeout=8)
        if r.status_code == 200:
            return "".join([p[0] for p in r.json()[0] if p and p[0]]).strip()
    except Exception:
        pass
    return text

def parse_llm_translation_response(raw_text, expected_ids):
    res_map = {}
    if not raw_text:
        return res_map
    raw_text = re.sub(r"^```[a-zA-Z0-9_-]*\n", "", raw_text.strip(), flags=re.MULTILINE)
    raw_text = re.sub(r"\n```$", "", raw_text.strip(), flags=re.MULTILINE)

    matches = re.finditer(r'\[\[ID_(\d+)\]\]\s*(.*?)(?=\[\[ID_\d+\]\]|$|\n)', raw_text, re.DOTALL)
    for m in matches:
        sid = int(m.group(1))
        val = m.group(2).strip()
        if val and sid in expected_ids:
            res_map[sid] = val

    for line in raw_text.splitlines():
        line = line.strip()
        if not line:
            continue
        m = re.match(r'^(?:\[\s*|ID\s*|#\s*)?(\d+)(?:\])?\s*[\:\.\|\-\t\uff5c\uff1a]\s*(.+)$', line)
        if m:
            sid = int(m.group(1))
            val = m.group(2).strip()
            if sid in expected_ids and sid not in res_map and val:
                res_map[sid] = val

    return res_map

def call_gemini_single_batch(api_keys, start_key_idx, preferred_model, prompt_text):
    valid_models = []
    for m in [preferred_model, "gemini-3.5-flash", "gemini-3.5-flash-lite", "gemini-3.8-flash", "gemini-2.5-flash", "gemini-2.0-flash", "gemini-1.5-flash"]:
        if m and m not in valid_models:
            valid_models.append(m)

    base_payload = {"contents": [{"parts": [{"text": prompt_text}]}], "generationConfig": {"temperature": 0.15}}
    last_error = ""
    for k_offset in range(len(api_keys)):
        api_key = api_keys[(start_key_idx + k_offset) % len(api_keys)]
        for model_name in valid_models:
            url = f"https://generativelanguage.googleapis.com/v1beta/models/{model_name}:generateContent?key={api_key}"
            try:
                payload = json.loads(json.dumps(base_payload))
                if "thinking" in model_name:
                    payload["generationConfig"]["thinkingConfig"] = {"thinkingBudget": 0}
                resp = requests.post(url, json=payload, timeout=90)
                if resp.status_code == 400 and "thinkingConfig" in resp.text:
                    resp = requests.post(url, json=base_payload, timeout=90)
                if resp.status_code == 200:
                    return resp.json(), model_name, None
                elif resp.status_code == 429:
                    last_error = f"Model {model_name} bị giới hạn tần suất (429 Rate Limit)"
                    break
                else:
                    last_error = f"API trả về mã {resp.status_code}: {resp.text[:120]}"
            except Exception as e:
                last_error = str(e)
    return None, preferred_model, last_error

@app.route("/api/context/analyze", methods=["POST"])
def api_analyze_context():
    data = request.json
    api_keys = [k.strip() for k in data.get("apiKeys", []) if k and k.strip()]
    preferred_model = data.get("model", "gemini-3.5-flash")
    target_lang_label = data.get("targetLangLabel", "Tiếng Việt")
    segments = data.get("segments", [])
    if not api_keys or not segments:
        return jsonify({"error": "Thiếu API Key hoặc phụ đề!"}), 400

    update_progress(35, f"Đang quét kịch bản để khóa Ngữ cảnh & Xưng hô cho [{target_lang_label}]...")
    sample_text = "\n".join([f"{s['id']}. {s['text']}" for s in segments[::max(1, len(segments)//35)][:40]])
    prompt = f"Lập BẢNG QUY CHUẨN NGỮ CẢNH ngắn gọn (<100 từ) gồm Chủ đề, Cặp xưng hô/văn phong bắt buộc trong {target_lang_label}, và Thuật ngữ cho kịch bản sau:\n{sample_text}"
    res_json, _, _ = call_gemini_single_batch(api_keys, 0, preferred_model, prompt)
    bible = ""
    if res_json and "candidates" in res_json and res_json["candidates"]:
        try:
            bible = res_json["candidates"][0]["content"]["parts"][0]["text"].strip()
        except Exception:
            pass
    update_progress(100, "Đã hoàn tất phân tích Ngữ cảnh!")
    return jsonify({"context_summary": bible})

@app.route("/api/gemini/validate_keys", methods=["POST"])
def api_validate_gemini_keys():
    data = request.json or {}
    keys = data.get("keys", [])
    if isinstance(keys, str):
        keys = [k.strip() for k in re.split(r"[\n,;]+", keys) if len(k.strip()) > 10]
    elif isinstance(keys, list):
        keys = [k.strip() for k in keys if k and len(k.strip()) > 10]

    if not keys:
        return jsonify({"results": [], "valid_count": 0, "error": "Chưa có key nào để kiểm tra!"})

    results = []
    for k in keys:
        masked = k[:6] + "..." + k[-4:] if len(k) > 10 else k
        payload = {"contents": [{"parts": [{"text": "Hi"}]}], "generationConfig": {"maxOutputTokens": 3}}
        ok = False
        status_msg = "Không dùng được"
        for test_m in ["gemini-3.5-flash", "gemini-3.5-flash-lite", "gemini-3.8-flash", "gemini-2.5-flash", "gemini-2.0-flash"]:
            url = f"https://generativelanguage.googleapis.com/v1beta/models/{test_m}:generateContent?key={k}"
            try:
                r = requests.post(url, json=payload, timeout=8)
                if r.status_code == 200:
                    ok = True
                    status_msg = f"Hoạt động cực tốt ({test_m})"
                    break
                elif r.status_code == 429:
                    status_msg = "Hết hạn mức phút (Rate limit 429)"
                    break
                else:
                    err_msg = r.json().get("error", {}).get("message", f"Mã {r.status_code}") if r.text.startswith("{") else f"Mã {r.status_code}"
                    status_msg = f"Lỗi ({test_m}): {err_msg[:45]}"
            except Exception as e:
                status_msg = f"Lỗi kết nối ({str(e)[:30]})"

        results.append({"key": masked, "valid": ok, "status": status_msg})

    valid_c = sum(1 for r in results if r["valid"])
    return jsonify({"results": results, "valid_count": valid_c})

def do_translate_core(segments, api_keys=None, preferred_model="gemini-3.5-flash", target_lang="vi", target_lang_label="Tiếng Việt", google_lang_code="vi", pronoun_rule="auto", context_glossary="", engine="hybrid", force_all=False, progress_cb=None):
    if progress_cb is None:
        progress_cb = update_progress

    api_keys = [k.strip() for k in (api_keys or []) if k and k.strip()]
    if not segments:
        return segments, "", engine

    if force_all:
        target_indices = list(range(len(segments)))
    else:
        target_indices = [i for i, s in enumerate(segments) if not (s.get("trans") or "").strip()]

    locked_context = f"Ngôn ngữ đích: {target_lang_label}. Xưng hô/Văn phong: {pronoun_rule}. Ngữ cảnh: {context_glossary}"
    if not target_indices:
        progress_cb(100, "Tất cả các câu đều đã có bản dịch!")
        return segments, locked_context, engine

    seg_map = {s["id"]: s for s in segments}
    items_to_translate = [(segments[i]["id"], segments[i]["text"]) for i in target_indices]

    progress_cb(15, f"Bắt đầu dịch {len(items_to_translate)} câu sang [{target_lang_label}]...")
    translated_any = False

    # 1. Chế độ THUẦN GOOGLE TRANSLATE (Miễn phí 100%, không cần Key)
    if engine == "google" or (engine == "hybrid" and not api_keys):
        progress_cb(30, f"Đang dịch đa luồng qua Google Translate sang {target_lang_label}...")
        g_results = translate_google_batch(items_to_translate, target_lang=google_lang_code)
        for sid, t_val in g_results.items():
            if sid in seg_map and t_val.strip():
                seg_map[sid]["trans"] = t_val.strip()
                translated_any = True
        progress_cb(100, f"Hoàn tất dịch {len(g_results)} câu bằng Google Translate!")
        return segments, locked_context, "google"

    # Tự động phân tích nhanh ngữ cảnh hội thoại toàn kịch bản bằng Gemini nếu chưa có bảng ngữ cảnh
    if api_keys and not context_glossary and len(segments) > 0:
        try:
            progress_cb(18, "Đang quét nhanh bối cảnh thoại để khóa đại từ xưng hô chuẩn xác...")
            sample_lines = "\n".join([f"{s['id']}. {s['text']}" for s in segments[:18] if s.get("text")])
            quick_prompt = (
                f"Hãy phân tích nhanh các câu đối thoại sau để xác định thể loại video và quan hệ nhân vật:\n{sample_lines}\n"
                f"Cho biết thật ngắn gọn (<30 từ): Bối cảnh video và Cặp xưng hô tiếng Việt tự nhiên nhất (VD: anh-em, cậu-tớ, chú-cháu, tao-mày)."
            )
            q_res, _, _ = call_gemini_single_batch(api_keys, 0, preferred_model, quick_prompt)
            if q_res and "candidates" in q_res and q_res["candidates"]:
                tone_hint = q_res["candidates"][0]["content"]["parts"][0]["text"].strip()
                locked_context += f" | Nhận diện ngữ cảnh: {tone_hint}"
        except Exception:
            pass

    # 2. Chế độ GEMINI AI CHUẨN ĐIỆN ẢNH (Multi-Key Pool & Context-Aware Prompting)
    batch_size = 15
    index_batches = [target_indices[i:i + batch_size] for i in range(0, len(target_indices), batch_size)]

    def process_batch(b_idx, idx_list):
        b_items = [(segments[i]["id"], segments[i]["text"]) for i in idx_list]
        lines_input = "\n".join([f"[[ID_{segments[i]['id']}]] {segments[i]['text']}" for i in idx_list])

        # Kèm ngữ cảnh các câu trước đó để AI hiểu mạch hội thoại
        context_preview = ""
        prev_idx = max(0, idx_list[0] - 2)
        if prev_idx < idx_list[0]:
            prev_lines = [f"{segments[k]['text']}" for k in range(prev_idx, idx_list[0]) if segments[k].get("text")]
            if prev_lines:
                context_preview = f"Mạch đối thoại câu trước đó: {' // '.join(prev_lines)}\n"

        prompt = (
            f"Bạn là chuyên gia biên dịch phụ đề và lồng tiếng điện ảnh chuyên nghiệp hàng đầu.\n"
            f"Nhiệm vụ: Dịch kịch bản/phụ đề đối thoại sau sang [{target_lang_label}].\n"
            f"Định hướng ngữ cảnh: {locked_context}\n"
            f"{context_preview}"
            f"NGUYÊN TẮC BẮT BUỘC ĐỂ BẢN DỊCH CHUẨN XÁC 100%:\n"
            f"1. ĐÚNG NGỮ CẢNH & TỰ NHIÊN: Bắt trọn cảm xúc, ngữ điệu, quan hệ nhân vật. TUYỆT ĐỐI KHÔNG dịch thô 'tôi/bạn' lặp đi lặp lại như Google Dịch.\n"
            f"2. ĐẠI TỪ XƯNG HÔ LINH HOẠT: Sử dụng đại từ xưng hô tự nhiên trong giao tiếp đời thường của người Việt (anh/em, cậu/tớ, chú/cháu, ông/bà, bạn/mình, mày/tao) tùy thuộc ngữ cảnh thoại.\n"
            f"3. THÀNH NGỮ & TỪ LÓNG: Dịch thoát ý, mượt mà, đúng chất ngôn ngữ đời thường/phim ảnh, không dịch word-by-word.\n"
            f"4. ĐỘ DÀI PHÙ HỢP LỒNG TIẾNG: Câu văn cô đọng, vừa vặn nhịp thở để lồng tiếng AI (TTS) khớp thời gian hình ảnh.\n"
            f"5. BẮT BUỘC giữ nguyên định dạng [[ID_X]] Bản dịch cho từng câu:\n{lines_input}"
        )
        res_json, used_model, err = call_gemini_single_batch(api_keys, b_idx, preferred_model, prompt)
        return b_idx, res_json, b_items, err

    done = 0
    workers = min(len(index_batches), max(2, len(api_keys) * 2))
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures = [ex.submit(process_batch, idx, ib) for idx, ib in enumerate(index_batches)]
        for fut in as_completed(futures):
            b_idx, res_json, b_items, b_err = fut.result()
            done += 1
            batch_expected = {it[0] for it in b_items}
            parsed_res = {}

            if res_json and "candidates" in res_json and res_json["candidates"]:
                try:
                    raw_text = res_json["candidates"][0]["content"]["parts"][0]["text"].strip()
                    parsed_res = parse_llm_translation_response(raw_text, batch_expected)
                except Exception:
                    pass

            # Tự động Fallback sang Google Translate nếu câu nào bị sót hoặc Gemini lỗi lô đó
            missing_items = [it for it in b_items if it[0] not in parsed_res or not parsed_res[it[0]].strip()]
            if missing_items:
                g_fallback = translate_google_batch(missing_items, target_lang=google_lang_code)
                parsed_res.update(g_fallback)

            for sid, trans_val in parsed_res.items():
                if sid in seg_map and trans_val.strip():
                    seg_map[sid]["trans"] = trans_val.strip()
                    translated_any = True

            pct = 15 + int((done / max(1, len(index_batches))) * 83)
            progress_cb(min(98, pct), f"Đã dịch sang {target_lang_label} ({done}/{len(index_batches)} lô)...")

    # Kiểm tra an toàn: Đảm bảo có ít nhất 1 câu được dịch
    untranslated_count = len([s for s in segments if not (s.get("trans") or "").strip()])
    if not translated_any and untranslated_count == len(segments):
        print("[!] Gemini thất bại hoàn toàn, đang chạy cứu hộ qua Google Translate...")
        rescue_map = translate_google_batch(items_to_translate, target_lang=google_lang_code)
        for sid, t_val in rescue_map.items():
            if sid in seg_map and t_val.strip():
                seg_map[sid]["trans"] = t_val.strip()
                translated_any = True

    if not translated_any:
        raise RuntimeError("Không thể dịch phụ đề. Vui lòng kiểm tra lại kết nối mạng hoặc thử lại với Google Translate!")

    progress_cb(100, f"Hoàn tất dịch toàn bộ phụ đề sang {target_lang_label}!")
    return segments, locked_context, engine

@app.route("/translate", methods=["POST"])
def translate_subtitles():
    data = request.json or {}
    api_keys = [k.strip() for k in data.get("apiKeys", []) if k and k.strip()]
    preferred_model = data.get("model", "gemini-3.5-flash")
    target_lang = data.get("targetLang", "vi")
    target_lang_label = data.get("targetLangLabel", "Tiếng Việt")
    google_lang_code = data.get("googleLangCode", target_lang)
    pronoun_rule = data.get("pronounRule", "auto")
    context_glossary = data.get("contextGlossary", "").strip()
    segments = data.get("segments", [])
    engine = data.get("engine", "hybrid")
    force_all = data.get("forceAll", False)

    if not segments:
        return jsonify({"error": "Chưa có danh sách phụ đề để dịch!"}), 400

    try:
        updated_segs, locked_ctx, engine_used = do_translate_core(
            segments, api_keys, preferred_model, target_lang, target_lang_label,
            google_lang_code, pronoun_rule, context_glossary, engine, force_all
        )
        return jsonify({"segments": updated_segs, "locked_context": locked_ctx, "engine_used": engine_used})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

# ==================== CÁC API BỔ TRỢ QUẢN LÝ PHỤ ĐỀ CHUYÊN NGHIỆP ====================
@app.route("/api/translate_single", methods=["POST"])
def api_translate_single():
    """Dịch riêng lẻ 1 dòng phụ đề tức thì"""
    data = request.json or {}
    text = (data.get("text") or "").strip()
    target_lang = data.get("googleLangCode", data.get("targetLang", "vi"))
    if not text:
        return jsonify({"trans": ""})
    res = translate_single_text(text, target_lang=target_lang)
    return jsonify({"trans": res})

@app.route("/api/subtitles/offset", methods=["POST"])
def api_subtitles_offset():
    """Chỉnh dịch chuyển timeline toàn bộ hoặc dải phụ đề (Offset seconds)"""
    data = request.json or {}
    segments = data.get("segments", [])
    try:
        offset_sec = float(data.get("offset", 0.0))
    except ValueError:
        return jsonify({"error": "Giá trị offset không hợp lệ!"}), 400

    for s in segments:
        s["start"] = max(0.0, round(float(s["start"]) + offset_sec, 2))
        s["end"] = max(0.1, round(float(s["end"]) + offset_sec, 2))

    return jsonify({"segments": segments, "message": f"Đã chỉnh lệch giờ {offset_sec:+}s cho {len(segments)} câu!"})

@app.route("/api/subtitles/replace", methods=["POST"])
def api_subtitles_replace():
    """Tìm kiếm & thay thế hàng loạt từ ngữ trong phụ đề"""
    data = request.json or {}
    segments = data.get("segments", [])
    find_str = data.get("find", "").strip()
    replace_str = data.get("replace", "")
    target_col = data.get("target", "all") # 'all' | 'trans' | 'orig'
    match_case = data.get("matchCase", False)

    if not find_str:
        return jsonify({"error": "Từ khóa tìm kiếm không được để trống!"}), 400

    count = 0
    flags = 0 if match_case else re.IGNORECASE
    pattern = re.compile(re.escape(find_str), flags)

    for s in segments:
        if target_col in ("all", "orig") and "text" in s:
            new_text, n1 = pattern.subn(replace_str, s["text"])
            if n1:
                s["text"] = new_text
                count += n1
        if target_col in ("all", "trans") and "trans" in s:
            new_trans, n2 = pattern.subn(replace_str, s["trans"])
            if n2:
                s["trans"] = new_trans
                count += n2

    return jsonify({"segments": segments, "count": count, "message": f"Đã thay thế thành công {count} vị trí!"})

@app.route("/api/subtitles/clean", methods=["POST"])
def api_subtitles_clean():
    """Tự động chuẩn hóa câu chữ, viết hoa đầu câu, xóa khoảng trắng thừa"""
    data = request.json or {}
    segments = data.get("segments", [])
    for s in segments:
        for k in ("text", "trans"):
            val = (s.get(k) or "").strip()
            if val:
                val = re.sub(r"\s+", " ", val)
                val = val[0].upper() + val[1:] if len(val) > 1 else val.upper()
                s[k] = val
    return jsonify({"segments": segments, "message": f"Đã chuẩn hóa {len(segments)} câu phụ đề!"})

@app.route("/api/export_ass", methods=["POST"])
def api_export_ass():
    """Xuất file .ASS nguyên vẹn màu sắc & kiểu dáng chuyên nghiệp"""
    data = request.json or {}
    segments = data.get("segments", [])
    vid_path = os.path.join(TEMP_DIR, "input_video.mp4")
    vid_w, vid_h, total_dur = get_video_info(vid_path) if os.path.exists(vid_path) else (1280, 720, 0)
    
    st = data.get("settings", {})
    font_name = st.get("fontName", "Arial")
    font_size = int(st.get("fontSize", 22))
    text_color = st.get("textColor", "#FFFFFF")
    outline_color = st.get("outlineColor", "#000000")
    outline_width = int(st.get("outlineWidth", 2))
    margin_v = int(st.get("marginV", 28))
    target_lang = st.get("targetLang", "vi")

    ass_out = os.path.join(TEMP_DIR, "export_styled.ass")
    generate_ass_file(ass_out, segments, vid_w, vid_h, font_name, font_size, text_color, outline_color, outline_width, margin_v, target_lang)
    return send_file(ass_out, as_attachment=True, download_name="subtitles_styled.ass")

@app.route("/api/export_txt", methods=["POST"])
def api_export_txt():
    """Xuất kịch bản thuần text cho thu âm/lồng tiếng podcast"""
    data = request.json or {}
    segments = data.get("segments", [])
    mode = data.get("mode", "trans") # 'trans' | 'orig' | 'bi'
    
    lines = []
    for s in segments:
        sid = s.get("id", "")
        ot = (s.get("text") or "").strip()
        tr = (s.get("trans") or "").strip()
        if mode == "orig":
            lines.append(f"{sid}. {ot}")
        elif mode == "bi":
            lines.append(f"[{sid}] GỐC: {ot}\n    DỊCH: {tr}\n")
        else:
            lines.append(f"{sid}. {tr or ot}")
            
    txt_out = os.path.join(TEMP_DIR, "script.txt")
    with open(txt_out, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    return send_file(txt_out, as_attachment=True, download_name="script_dialogue.txt")

def do_render_core(segments, settings, video_path=None, output_path=None, work_dir=None, progress_cb=None):
    if progress_cb is None:
        progress_cb = update_progress

    work_dir = work_dir or TEMP_DIR
    os.makedirs(work_dir, exist_ok=True)
    video_path = video_path or os.path.join(work_dir, "input_video.mp4")
    if not os.path.exists(video_path):
        video_path = os.path.join(TEMP_DIR, "input_video.mp4")
    if not os.path.exists(video_path):
        raise FileNotFoundError("Không tìm thấy video đầu vào để render!")

    output_path = output_path or os.path.join(work_dir, "output_vietsub.mp4")

    target_lang = settings.get("targetLang", "vi")
    google_lang_code = settings.get("googleLangCode", target_lang)
    blur_rect = settings.get("blurRect", {"x": 0, "y": 0, "w": 0, "h": 0})
    blur_opacity = float(settings.get("blurOpacity", 0)) / 100.0
    blur_sigma = int(settings.get("blurSigma", 14))
    blur_color = str(settings.get("blurColor", "#000000")).lstrip("#")

    font_name = settings.get("fontName", "Arial")
    font_size = int(settings.get("fontSize", 22))
    text_color = settings.get("textColor", "#FFFFFF")
    outline_color = settings.get("outlineColor", "#000000")
    outline_width = int(settings.get("outlineWidth", 2))
    margin_v = int(settings.get("marginV", 28))

    enable_tts = settings.get("enableTts", True)
    tts_voice = settings.get("ttsVoice", "piper:vi_VN-vais1000-medium")
    tts_threads = int(settings.get("ttsThreads", 16))
    reuse_audio_cache = settings.get("reuseAudioCache", True)
    orig_volume = float(settings.get("origVolume", 0.15))
    render_mode = settings.get("renderMode", "hybrid_gpu")

    vid_w, vid_h, total_dur = get_video_info(video_path)

    # Tự động quét SmartBlur nếu chưa vẽ
    if int(blur_rect.get("w", 0)) < 10 and int(blur_rect.get("h", 0)) < 10 and render_mode != "copy":
        try:
            sb_res = auto_detect_smartblur_fullrow(
                video_path,
                scan_minutes=ADDON_SETTINGS.get("smartblur_scan_minutes", 4),
                pad_y=ADDON_SETTINGS.get("smartblur_pad_y", 14),
                progress_cb=progress_cb
            )
            blur_rect = {"x": sb_res["x"], "y": sb_res["y"], "w": sb_res["w"], "h": sb_res["h"]}
        except Exception as e_sb:
            print(f"[!] SmartBlur auto detect notice: {e_sb}")

    srt_path = os.path.join(work_dir, "sub_vi.srt")
    with open(srt_path, "w", encoding="utf-8") as f:
        for idx, seg in enumerate(segments, start=1):
            f.write(f"{idx}\n{format_srt_time(seg['start'])} --> {format_srt_time(seg['end'])}\n{(seg.get('trans') or seg.get('text') or '').strip()}\n\n")

    generate_vtt_file(os.path.join(work_dir, "sub_vi.vtt"), segments)
    ass_path = os.path.join(work_dir, "sub_vi.ass")
    generate_ass_file(ass_path, segments, vid_w, vid_h, font_name, font_size, text_color, outline_color, outline_width, margin_v, target_lang)

    inject_dvd_bouncing_text_into_ass(ass_path, vid_w, vid_h, total_dur, ADDON_SETTINGS)

    final_audio_path = os.path.join(work_dir, "mixed_audio.aac")
    if enable_tts and segments:
        cache_dir = os.path.join(TEMP_DIR, "tts_cache")
        os.makedirs(cache_dir, exist_ok=True)
        total = len(segments)
        done_cnt = 0

        def make_one_audio(seg):
            nonlocal done_cnt
            txt = (seg.get("trans") or seg.get("text") or "").strip()
            if not txt:
                return None
            ckey = get_tts_cache_key(tts_voice, txt)
            cfile = os.path.join(cache_dir, f"{ckey}.mp3")

            if not (reuse_audio_cache and os.path.exists(cfile) and os.path.getsize(cfile) > 100):
                ok = False
                if tts_voice.startswith("piper:"):
                    ok = synthesize_with_piper(txt, tts_voice, cfile)
                elif not tts_voice.startswith("google:"):
                    try:
                        asyncio.run(edge_tts.Communicate(txt, tts_voice).save(cfile))
                        ok = os.path.exists(cfile) and os.path.getsize(cfile) > 100
                    except Exception:
                        ok = False
                if not ok:
                    g_tl = tts_voice.split(":", 1)[1] if tts_voice.startswith("google:") else google_lang_code
                    r = requests.get("https://translate.googleapis.com/translate_tts", params={"ie": "UTF-8", "q": txt[:200], "tl": g_tl, "client": "tw-ob"}, timeout=12)
                    if r.status_code == 200:
                        with open(cfile, "wb") as f:
                            f.write(r.content)

            done_cnt += 1
            progress_cb(15 + int((done_cnt / max(1, total)) * 45), f"Đang tạo giọng đọc ({done_cnt}/{total} câu)...")

            if not os.path.exists(cfile):
                return None
            try:
                clip = AudioSegment.from_file(cfile)
                return (seg["id"], clip, len(clip) / 1000.0)
            except Exception:
                return None

        sync_mode = settings.get("syncMode", "retime_video")
        # Video dài (>150 câu hoặc >600s) tự động dùng atempo để đảm bảo ổn định 100%, chống tràn RAM và sập filter FFmpeg
        if sync_mode == "retime_video" and (len(segments) > 150 or total_dur > 600):
            print(f"[RETIME GUARD LOCAL] Video dài ({len(segments)} câu, {total_dur:.0f}s). Tự động dùng chế độ atempo đồng bộ audio siêu tốc để đảm bảo ổn định 100%!", flush=True)
            sync_mode = "atempo"

        audio_clips = {}
        audio_durs = {}
        synced_results = []
        with ThreadPoolExecutor(max_workers=max(4, min(16, tts_threads))) as ex:
            for res in ex.map(make_one_audio, segments):
                if res:
                    synced_results.append(res)
                    audio_clips[res[0]] = res[1]
                    audio_durs[res[0]] = res[2]

        synced_items = []

        if sync_mode == "retime_video" and audio_clips:
            progress_cb(62, "Đang tính toán co giãn Video theo giọng đọc tự nhiên 1.0x...")
            intervals = []
            cur_orig = 0.0
            new_timeline = 0.0
            new_segments = []

            for seg in segments:
                s_start, s_end = float(seg["start"]), float(seg["end"])
                if s_start > cur_orig:
                    gap_dur = s_start - cur_orig
                    intervals.append({"t0": cur_orig, "t1": s_start, "mult": 1.0, "out_dur": gap_dur})
                    new_timeline += gap_dur
                    cur_orig = s_start

                v_dur = max(0.2, s_end - s_start)
                a_dur = audio_durs.get(seg["id"], v_dur)
                if a_dur > v_dur:
                    mult = a_dur / v_dur
                    out_dur = a_dur
                else:
                    mult = 1.0
                    out_dur = v_dur

                intervals.append({"t0": s_start, "t1": s_end, "mult": mult, "out_dur": out_dur})
                new_s = dict(seg)
                new_s["start"] = round(new_timeline, 2)
                new_s["end"] = round(new_timeline + out_dur, 2)
                new_segments.append(new_s)
                new_timeline += out_dur
                cur_orig = s_end

            if total_dur > cur_orig:
                gap_dur = total_dur - cur_orig
                intervals.append({"t0": cur_orig, "t1": total_dur, "mult": 1.0, "out_dur": gap_dur})
                new_timeline += gap_dur

            need_retime = any(abs(it["mult"] - 1.0) > 0.02 for it in intervals)
            if need_retime and len(intervals) > 0 and len(intervals) <= 150:
                progress_cb(65, "Đang khớp chuyển động Video theo nhịp câu nói...")
                retime_script = os.path.join(work_dir, "retime_filter.txt")
                N = len(intervals)
                splits = ''.join(f'[v{i}]' for i in range(N))
                f_lines = [f'[0:v]split={N}{splits}']
                parts = []
                for i, it in enumerate(intervals):
                    t0, t1, mult = it["t0"], it["t1"], it["mult"]
                    if abs(mult - 1.0) < 0.02:
                        f_lines.append(f'[v{i}]trim={t0:.3f}:{t1:.3f},setpts=PTS-STARTPTS[p{i}]')
                    else:
                        f_lines.append(f'[v{i}]trim={t0:.3f}:{t1:.3f},setpts={mult:.4f}*(PTS-STARTPTS)[p{i}]')
                    parts.append(f'[p{i}]')
                joined_p = ''.join(parts)
                f_lines.append(f'{joined_p}concat=n={N}:v=1:a=0[outv_retime]')
                with open(retime_script, "w", encoding="utf-8") as rf:
                    rf.write(";\n".join(f_lines))

                retimed_mp4 = os.path.join(work_dir, "retimed_video.mp4")
                cmd_ret = ["ffmpeg", "-y", "-i", video_path, "-filter_complex_script", retime_script, "-map", "[outv_retime]", "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", retimed_mp4]
                p_ret = subprocess.run(cmd_ret, capture_output=True, text=True)
                if p_ret.returncode == 0 and os.path.exists(retimed_mp4) and os.path.getsize(retimed_mp4) > 1000:
                    video_path = retimed_mp4
                    vid_w, vid_h, total_dur = get_video_info(video_path)
                    segments = new_segments
                    generate_ass_file(ass_path, segments, vid_w, vid_h, font_name, font_size, text_color, outline_color, outline_width, margin_v, target_lang)
                    inject_dvd_bouncing_text_into_ass(ass_path, vid_w, vid_h, total_dur, ADDON_SETTINGS)

            for seg in segments:
                clip = audio_clips.get(seg["id"])
                if clip:
                    synced_items.append((float(seg["start"]), clip))

        else:
            progress_cb(62, "Đang đồng bộ tốc độ âm thanh khớp Timeline...")
            done_sync = 0
            total_sync = len(segments)
            for seg in segments:
                clip = audio_clips.get(seg["id"])
                if not clip: continue
                s_sec, e_sec = float(seg["start"]), float(seg["end"])
                s_ms, e_ms = int(s_sec * 1000), int(e_sec * 1000)
                t_dur = max(300, e_ms - s_ms)
                if len(clip) > t_dur:
                    ratio = min(1.85, len(clip) / t_dur)
                    ckey = get_tts_cache_key(tts_voice, (seg.get("trans") or seg.get("text") or "").strip())
                    f_path = os.path.join(cache_dir, f"{ckey}_{t_dur}.mp3")
                    if not (reuse_audio_cache and os.path.exists(f_path)):
                        subprocess.run(["ffmpeg", "-y", "-i", os.path.join(cache_dir, f"{ckey}.mp3"), "-filter:a", f"atempo={ratio:.3f}", f_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    if os.path.exists(f_path):
                        clip = AudioSegment.from_file(f_path)
                synced_items.append((s_sec, clip))
                done_sync += 1
                if done_sync % 100 == 0 or done_sync == total_sync:
                    progress_cb(62 + int((done_sync / max(1, total_sync)) * 8), f"Đang đồng bộ âm thanh ({done_sync}/{total_sync} câu)...")

        # TRỘN ÂM THANH SIÊU TỐC BẰNG NUMPY HIGH-SPEED BUFFER + FFMPEG NATIVE AMIX
        progress_cb(72, "Đang hòa trộn dải âm thanh lồng tiếng siêu tốc (Numpy High-Speed Mixer)...")
        SR = 24000
        max_end_time = max((s[0] + 5.0 for s in synced_items), default=total_dur + 5.0)
        total_audio_sec = max(total_dur + 5.0, max_end_time)
        total_samples = int(total_audio_sec * SR) + SR * 2
        voice_track_wav = os.path.join(work_dir, "voice_track.wav")

        try:
            voice_buf = np.zeros(total_samples, dtype=np.int16)
            for s_sec, clip in synced_items:
                try:
                    c = clip.set_frame_rate(SR).set_channels(1).set_sample_width(2)
                    c_data = np.frombuffer(c.raw_data, dtype=np.int16)
                    st_idx = int(s_sec * SR)
                    en_idx = min(st_idx + len(c_data), total_samples)
                    if en_idx > st_idx:
                        voice_buf[st_idx:en_idx] = np.clip(
                            voice_buf[st_idx:en_idx].astype(np.int32) + c_data[:en_idx - st_idx],
                            -32768, 32767
                        ).astype(np.int16)
                except Exception: pass

            with wave.open(voice_track_wav, "wb") as wf:
                wf.setnchannels(1)
                wf.setsampwidth(2)
                wf.setframerate(SR)
                wf.writeframes(voice_buf.tobytes())
            del voice_buf
        except Exception as e_mix:
            print(f"[!] Fallback tạo voice_track bằng pydub: {e_mix}")
            master_a = AudioSegment.silent(duration=int((total_dur + 5) * 1000))
            for s_sec, clip in synced_items:
                master_a = master_a.overlay(clip, position=int(s_sec * 1000))
            master_a.export(voice_track_wav, format="wav")
            del master_a

        if not os.path.exists(voice_track_wav):
            subprocess.run(["ffmpeg", "-y", "-f", "lavfi", "-i", "anullsrc=r=24000:cl=mono", "-t", f"{int(total_dur)+2}", voice_track_wav], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

        vol_mult = orig_volume / 100.0 if orig_volume > 1.0 else orig_volume
        if has_audio_stream(video_path) and vol_mult > 0.01:
            progress_cb(75, "Đang hòa trộn giọng đọc AI và âm nền video gốc (FFmpeg Native amix)...")
            amix_cmd = [
                "ffmpeg", "-y", "-i", video_path, "-i", voice_track_wav,
                "-filter_complex", f"[0:a]volume={vol_mult:.3f}[a0];[1:a]volume=1.0[a1];[a0][a1]amix=inputs=2:duration=first:dropout_transition=2[aout]",
                "-map", "[aout]", "-c:a", "pcm_s16le", final_audio_path
            ]
            p_mix = subprocess.run(amix_cmd, capture_output=True, text=True)
            if p_mix.returncode != 0 or not os.path.exists(final_audio_path) or os.path.getsize(final_audio_path) < 1000:
                shutil.copyfile(voice_track_wav, final_audio_path)
        else:
            shutil.copyfile(voice_track_wav, final_audio_path)

        if os.path.exists(voice_track_wav):
            try: os.remove(voice_track_wav)
            except Exception: pass

    # Render video
    if render_mode == "copy":
        cmd = ["ffmpeg", "-y", "-i", video_path, "-i", final_audio_path, "-i", srt_path, "-map", "0:v:0", "-map", "1:a:0", "-map", "2:s:0", "-c:v", "copy", "-c:a", "copy", "-c:s", "mov_text", "-movflags", "+faststart", output_path]
        res_copy = subprocess.run(cmd, capture_output=True, text=True, errors="replace")
        if res_copy.returncode != 0:
            raise RuntimeError(f"FFmpeg copy thất bại: {(res_copy.stderr or '')[-300:].strip()}")
        progress_cb(100, "⚡ Xuất tức thì hoàn tất!")
        try:
            eff_ws = get_workspace_id()
            sz_mb = round(os.path.getsize(output_path) / (1024 * 1024), 2) if os.path.exists(output_path) else 0.0
            record_video_history(eff_ws, {
                "title": os.path.basename(video_path or "output_vietsub.mp4"),
                "filename": os.path.basename(output_path),
                "file_path": output_path,
                "file_size_mb": sz_mb
            })
        except Exception:
            pass
        return {"status": "ok", "render_mode": "copy", "badge_label": "⚡ Xuất Tức Thì", "output_path": output_path}

    blur_areas = settings.get("blurAreas") or settings.get("blur_areas") or []
    logo_path = os.path.join(TEMP_DIR, "watermark_logo.png")
    vf_chain, use_logo = build_filter_complex_with_logo(
        vid_w, vid_h, blur_rect, blur_sigma, blur_opacity, blur_color,
        ass_filename=ass_path, logo_path=logo_path, addon_cfg=ADDON_SETTINGS,
        blur_areas=blur_areas
    )

    cmd = ["ffmpeg", "-y", "-i", video_path]
    audio_input_idx = None
    next_input_idx = 1

    if enable_tts and os.path.exists(final_audio_path):
        cmd += ["-i", final_audio_path]
        audio_input_idx = next_input_idx
        next_input_idx += 1

    if use_logo:
        cmd += ["-i", logo_path]
        vf_chain = vf_chain.replace("[LOGO_IN]", f"[{next_input_idx}:v]")

    cmd += ["-filter_complex", vf_chain, "-map", "[outv]"]
    if audio_input_idx is not None:
        cmd += ["-map", f"{audio_input_idx}:a"]
    else:
        cmd += ["-map", "0:a?"]

    cmd += ["-c:v", "libx264", "-preset", "ultrafast", "-crf", "21", "-movflags", "+faststart", "-c:a", "aac", "-b:a", "192k", output_path]
    res_ffmpeg = subprocess.run(cmd, capture_output=True, text=True, errors="replace")
    if res_ffmpeg.returncode != 0:
        err_tail = (res_ffmpeg.stderr or "")[-350:].strip()
        print(f"[!] Lỗi FFmpeg render: {err_tail}", flush=True)
        raise RuntimeError(f"FFmpeg render thất bại: {err_tail}")
    progress_cb(100, "Xuất Video hoàn tất 100%!")
    try:
        eff_ws = get_workspace_id()
        sz_mb = round(os.path.getsize(output_path) / (1024 * 1024), 2) if os.path.exists(output_path) else 0.0
        record_video_history(eff_ws, {
            "title": os.path.basename(video_path or "output_vietsub.mp4"),
            "filename": os.path.basename(output_path),
            "file_path": output_path,
            "file_size_mb": sz_mb
        })
    except Exception:
        pass
    return {"status": "ok", "render_mode": render_mode, "badge_label": "Hoàn tất 100%", "output_path": output_path}

@app.route("/render", methods=["POST"])
def render_local_video():
    """Render tại máy Trạm Local (Kết hợp Piper ONNX + SmartBlur Full-Row + Chữ mờ DVD + Logo)"""
    data = request.json or {}
    segments = data.get("segments", [])
    if not segments:
        return jsonify({"error": "Chưa có danh sách phụ đề để render!"}), 400

    ws_dir = get_workspace_dir(request)
    video_path = os.path.join(ws_dir, "input_video.mp4")
    if not os.path.exists(video_path):
        video_path = os.path.join(TEMP_DIR, "input_video.mp4")
    if not os.path.exists(video_path):
        return jsonify({"error": "Không tìm thấy video gốc!"}), 400

    out_file = os.path.join(ws_dir, "output_vietsub.mp4")
    try:
        res = do_render_core(segments, data, video_path=video_path, output_path=out_file, work_dir=ws_dir)
        try:
            shutil.copy2(out_file, os.path.join(TEMP_DIR, "output_vietsub.mp4"))
        except Exception:
            pass
        return jsonify({"status": "ok", "render_mode": res.get("render_mode", "hybrid_gpu"), "badge_label": res.get("badge_label", "Hoàn tất 100%"), "output_url": "/temp_session/output_vietsub.mp4"})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

# ==================== MODULE 12: HỆ THỐNG NỀN TẢNG 24/7 & BẢO MẬT BẢN QUYỀN ====================

def run_server_auto_pipeline_thread(job_id, settings, api_keys, engine, initial_segments, device_id, target_hw="github", ws_id=None, relay_url=None):
    job_dir = os.path.join(SERVER_JOBS_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)
    ws_dir = os.path.join(WORKSPACES_ROOT, f"ws_{ws_id}") if ws_id else TEMP_DIR
    video_path = os.path.join(ws_dir, "input_video.mp4")
    if not os.path.exists(video_path):
        video_path = os.path.join(TEMP_DIR, "input_video.mp4")
    job_video_path = os.path.join(job_dir, "input_video.mp4")

    if os.path.exists(video_path) and not os.path.exists(job_video_path):
        try:
            shutil.copy2(video_path, job_video_path)
        except Exception:
            job_video_path = video_path

    active_video = job_video_path if os.path.exists(job_video_path) else video_path
    source_url = f"/api/pipeline/job_video/{job_id}/input_video.mp4"

    def update_job(pct, msg, step=None, status="running", error=None, output_url=None, segments=None):
        with SERVER_JOBS_LOCK:
            job = ACTIVE_SERVER_JOBS.get(job_id, {
                "job_id": job_id,
                "device_id": device_id,
                "workspace_id": ws_id,
                "created_at": datetime.now().isoformat()
            })
            job["percent"] = int(pct)
            job["message"] = str(msg or "")
            job["source_url"] = source_url
            job["workspace_id"] = ws_id
            job["updated_at"] = datetime.now().isoformat()
            if step: job["step"] = step
            if status: job["status"] = status
            if error:
                job["error"] = str(error)
            elif status == "error":
                job["error"] = str(msg) if str(msg).strip() else "Đã xảy ra lỗi trong tiến trình xử lý máy chủ."
            if output_url: job["output_url"] = output_url
            if segments is not None: job["segments"] = segments
            ACTIVE_SERVER_JOBS[job_id] = job
            update_progress(pct, msg, ws_id=ws_id)
            try:
                with open(os.path.join(job_dir, "state.json"), "w", encoding="utf-8") as f:
                    json.dump(job, f, ensure_ascii=False, indent=2)
            except Exception:
                pass
        update_progress(pct, msg)

    # TRƯỜNG HỢP 1: LOCAL PC OFFLINE (Chỉ khi người dùng chọn 'local' VÀ KHÔNG chạy trên Railway/Cloud)
    is_cloud_env = bool(os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("PORT"))
    if target_hw == "local" and not is_cloud_env:
        try:
            update_job(5, "Khởi động tiến trình xử lý cục bộ trên máy...", step="transcribe")
            segments = initial_segments or []
            if not segments:
                update_job(10, "Bắt đầu trích xuất âm thanh & phụ đề Whisper...", step="transcribe")
                model_size = settings.get("whisperModel", "small")
                device_req = settings.get("whisperDevice", "auto")
                src_lang = settings.get("whisperSourceLang", "auto")
                def trans_cb(p, m): update_job(10 + int(p * 0.25), m, step="transcribe")
                segments, detected_lang, _ = do_transcribe_core(active_video, model_size, device_req, src_lang, trans_cb)
                update_job(35, f"Hoàn tất trích xuất {len(segments)} câu phụ đề!", step="transcribe", segments=segments)
            else:
                update_job(35, f"Sử dụng {len(segments)} câu phụ đề có sẵn...", step="transcribe", segments=segments)

            update_job(38, "Bắt đầu dịch thuật tự động...", step="translate")
            target_lang = settings.get("targetLang", "vi")
            target_lang_label = settings.get("targetLangLabel", "Tiếng Việt")
            google_lang_code = settings.get("googleLangCode", target_lang)
            pronoun_rule = settings.get("pronounRule", "auto")
            context_glossary = settings.get("contextGlossary", "")
            pref_model = settings.get("geminiModel", "gemini-3.5-flash")

            def translat_cb(p, m): update_job(38 + int(p * 0.32), m, step="translate")
            segments, locked_ctx, _ = do_translate_core(
                segments, api_keys, pref_model, target_lang, target_lang_label,
                google_lang_code, pronoun_rule, context_glossary, engine, False, translat_cb
            )
            update_job(70, f"Hoàn tất dịch thuật sang {target_lang_label}!", step="translate", segments=segments)

            update_job(72, "Bắt đầu Render Video...", step="render")
            job_out_mp4 = os.path.join(job_dir, "output_vietsub.mp4")
            def render_cb(p, m): update_job(72 + int(p * 0.27), m, step="render")
            do_render_core(segments, settings, active_video, job_out_mp4, job_dir, render_cb)

            try:
                shutil.copy2(job_out_mp4, os.path.join(TEMP_DIR, "output_vietsub.mp4"))
            except Exception:
                pass

            out_url = f"/api/pipeline/job_video/{job_id}/output_vietsub.mp4"
            update_job(100, "🎉 Xuất Video hoàn tất 100%!", step="done", status="completed", output_url=out_url, segments=segments)
        except Exception as e:
            err_msg = str(e).strip() or "Lỗi xử lý local"
            update_job(0, f"Lỗi: {err_msg}", status="error", error=err_msg)
        return

    # TRƯỜNG HỢP 2: TRẠM TRUNG CHUYỂN CLOUD (ĐẨY TOÀN BỘ SANG GITHUB ACTIONS VPS HOẶC KAGGLE GPU 24/7)
    try:
        provider = "kaggle" if target_hw in ("kaggle", "gpu") else "github"
        provider_label = "Kaggle NVIDIA T4 GPU" if provider == "kaggle" else "GitHub Actions VPS (Multi-core 16GB)"

        update_job(3, f"Trạm Trung Chuyển đang chuẩn bị cấu hình & đẩy Job sang {provider_label}...", step="dispatch")

        # SmartBlur auto-detect nếu chưa vẽ vùng che mờ
        br = settings.get("blurRect", {"x": 0, "y": 0, "w": 0, "h": 0})
        if int(br.get("w", 0)) < 10 and int(br.get("h", 0)) < 10 and settings.get("renderMode") != "copy":
            try:
                sb_res = auto_detect_smartblur_fullrow(
                    active_video,
                    scan_minutes=ADDON_SETTINGS.get("smartblur_scan_minutes", 4),
                    pad_y=ADDON_SETTINGS.get("smartblur_pad_y", 6),
                    progress_cb=update_progress
                )
                settings["blurRect"] = {"x": sb_res["x"], "y": sb_res["y"], "w": sb_res["w"], "h": sb_res["h"]}
            except Exception:
                pass

        job_payload = {
            "provider": provider,
            "task_mode": "full",
            "segments": initial_segments or [],
            "apiKeys": api_keys or [],
            "engine": engine or "hybrid",
            "geminiModel": settings.get("geminiModel", "gemini-3.5-flash"),
            "whisperModel": settings.get("whisperModel", "small"),
            "settings": settings,
            "addon_settings": dict(ADDON_SETTINGS),
            "has_logo": os.path.exists(os.path.join(TEMP_DIR, "watermark_logo.png"))
        }

        # Lưu file config cho Worker tải về
        with open(os.path.join(TEMP_DIR, f"{job_id}_config.json"), "w", encoding="utf-8") as f:
            json.dump(job_payload, f, ensure_ascii=False)
        with open(os.path.join(job_dir, "config.json"), "w", encoding="utf-8") as f:
            json.dump(job_payload, f, ensure_ascii=False)

        ACTIVE_CLOUD_JOB.update({
            "job_id": job_id,
            "provider": provider,
            "status": "running",
            "task_mode": "full",
            "segments": initial_segments or [],
            "locked_context": "",
            "error": None,
            "output_ready": False
        })

        update_job(6, f"Đang gửi lệnh kích hoạt tiến trình 24/7 sang {provider_label}...", step="dispatch")

        if provider == "kaggle":
            dispatch_kaggle_t4_worker(job_id, ws_id=ws_id)
        else:
            dispatch_github_vps_worker(job_id, relay_url=relay_url, ws_id=ws_id)

        update_job(10, f"Đã kết nối thành công với {provider_label}! Đang chờ Worker nhận Video từ Trạm Trung Chuyển...", step="running")

    except Exception as e:
        import traceback
        tb = traceback.format_exc()
        err_msg = str(e).strip() or "Lỗi điều phối tiến trình sang Cloud Worker"
        print(f"[!] Lỗi Dispatch Job {job_id}: {err_msg}\n{tb}", flush=True)
        update_job(0, f"Lỗi khởi chạy 24/7: {err_msg}", status="error", error=err_msg)
        ACTIVE_CLOUD_JOB["status"] = "failed"
        ACTIVE_CLOUD_JOB["error"] = err_msg

@app.route("/api/pipeline/start_auto", methods=["POST"])
def api_pipeline_start_auto():
    data = request.json or {}
    dev_id = request.headers.get("X-Nexus-Device") or data.get("device_id", "DEV-UNKNOWN")
    token = request.headers.get("X-Nexus-Session") or request.cookies.get("nexus_session_token", "")
    ua = request.user_agent.string or ""

    # Bắt buộc xác thực bản quyền thiết bị
    ok, reason, payload = validate_session_token(token, dev_id, ua)
    if not ok:
        return jsonify({"error": f"Yêu cầu kích hoạt bản quyền: {reason}", "require_license": True}), 403

    key_str = payload if isinstance(payload, str) else (payload.get("key_str", "") if isinstance(payload, dict) else str(payload or ""))
    db = load_license_db()
    k_rec = db.get("keys", {}).get(key_str, {})
    tier = k_rec.get("tier", "pro")
    quota_limit = k_rec.get("quota_limit", 50)
    quota_used = k_rec.get("quota_used", 0)

    # Kiểm tra hạn mức sử dụng (Quota)
    if quota_limit != -1 and quota_used >= quota_limit:
        return jsonify({
            "error": f"❌ Key của bạn đã hết hạn mức sử dụng ({quota_used}/{quota_limit} lượt)! Vui lòng liên hệ Admin để nạp thêm lượt.",
            "quota_exceeded": True
        }), 403

    # Kiểm tra quyền dùng phần cứng GPU
    target_hw = data.get("hardware") or data.get("target", "github")
    if target_hw == "server_247":
        target_hw = "github"
    if target_hw in ("kaggle", "gpu") and tier == "basic":
        return jsonify({
            "error": "⚠️ Gói Key Basic chỉ hỗ trợ xử lý CPU (GitHub Actions VPS). Vui lòng nâng cấp lên Key PRO để sử dụng GPU Siêu Tốc (Kaggle NVIDIA T4)!",
            "require_pro": True
        }), 403

    ws_id = get_workspace_id(request)
    ws_dir = get_workspace_dir(request)
    video_path = os.path.join(ws_dir, "input_video.mp4")
    if not os.path.exists(video_path) or os.path.getsize(video_path) < 100:
        if dev_id:
            dev_hash = hashlib.sha256(dev_id.encode("utf-8")).hexdigest()[:10]
            dev_v = os.path.join(WORKSPACES_ROOT, f"ws_dev_{dev_hash}", "input_video.mp4")
            if os.path.exists(dev_v) and os.path.getsize(dev_v) > 100:
                video_path = dev_v
                try:
                    os.makedirs(ws_dir, exist_ok=True)
                    shutil.copy2(dev_v, os.path.join(ws_dir, "input_video.mp4"))
                except Exception:
                    pass
    if not os.path.exists(video_path) or os.path.getsize(video_path) < 100:
        video_path = os.path.join(TEMP_DIR, "input_video.mp4")
    if not os.path.exists(video_path) or os.path.getsize(video_path) < 100:
        def_v = os.path.join(WORKSPACES_ROOT, "ws_default", "input_video.mp4")
        if os.path.exists(def_v) and os.path.getsize(def_v) > 100:
            video_path = def_v
            try:
                os.makedirs(ws_dir, exist_ok=True)
                shutil.copy2(def_v, os.path.join(ws_dir, "input_video.mp4"))
            except Exception:
                pass
    if not os.path.exists(video_path) or os.path.getsize(video_path) < 100:
        return jsonify({"error": "Vui lòng tải video lên trước khi chạy tiến trình 24/7!"}), 400

    # Khấu trừ hạn mức 1 lượt
    consume_license_quota(key_str, 1, device_id=dev_id)

    settings = data.get("settings", {})
    api_keys = data.get("apiKeys", [])
    engine = data.get("engine", "hybrid")
    initial_segments = data.get("segments", [])
    req_relay_url = data.get("relay_url") or data.get("origin") or get_public_relay_url()

    job_id = f"job_{int(time.time())}_{uuid.uuid4().hex[:6]}"
    Thread(
        target=run_server_auto_pipeline_thread,
        args=(job_id, settings, api_keys, engine, initial_segments, dev_id, target_hw, ws_id, req_relay_url),
        daemon=True
    ).start()

    return jsonify({
        "status": "ok",
        "job_id": job_id,
        "message": "Trạm Trung Chuyển đã tiếp nhận và điều phối Job sang Worker xử lý ngầm 24/7!"
    })

@app.route("/api/pipeline/job_status/<job_id>")
def api_pipeline_job_status(job_id):
    with SERVER_JOBS_LOCK:
        job = ACTIVE_SERVER_JOBS.get(job_id)

    if not job:
        job_file = os.path.join(SERVER_JOBS_DIR, job_id, "state.json")
        if os.path.exists(job_file):
            try:
                with open(job_file, "r", encoding="utf-8") as f:
                    job = json.load(f)
                    with SERVER_JOBS_LOCK:
                        ACTIVE_SERVER_JOBS[job_id] = job
            except Exception:
                pass

    if not job:
        return jsonify({"status": "error", "error": "Không tìm thấy tiến trình 24/7 này trên máy chủ"}), 404

    return jsonify(job)

@app.route("/api/pipeline/active_job")
def api_pipeline_active_job():
    dev_id = request.args.get("device_id", "")
    saved_job_id = request.args.get("job_id", "")
    ws_id = get_workspace_id(request)
    ws_dir = get_workspace_dir(request)

    # 1. Kiểm tra theo job_id cụ thể nếu client có gửi (và phải thuộc về đúng workspace/thiết bị này)
    if saved_job_id:
        with SERVER_JOBS_LOCK:
            job = ACTIVE_SERVER_JOBS.get(saved_job_id)
        if not job:
            job_file = os.path.join(SERVER_JOBS_DIR, saved_job_id, "state.json")
            if os.path.exists(job_file):
                try:
                    with open(job_file, "r", encoding="utf-8") as f:
                        job = json.load(f)
                except Exception:
                    pass
        if job and (job.get("workspace_id") == ws_id or (dev_id and job.get("device_id") == dev_id)):
            return jsonify({"active": True, "job": job})

    # 2. Tìm job mới nhất của CHÍNH THIẾT BỊ HOẶC WORKSPACE NÀY (Không lấy của máy khác!)
    candidate_jobs = []
    with SERVER_JOBS_LOCK:
        for jid, j in ACTIVE_SERVER_JOBS.items():
            if (dev_id and j.get("device_id") == dev_id) or (ws_id and ws_id != "default" and j.get("workspace_id") == ws_id):
                candidate_jobs.append(j)

    if os.path.exists(SERVER_JOBS_DIR):
        for entry in os.scandir(SERVER_JOBS_DIR):
            if entry.is_dir():
                s_file = os.path.join(entry.path, "state.json")
                if os.path.exists(s_file):
                    try:
                        with open(s_file, "r", encoding="utf-8") as f:
                            cand = json.load(f)
                            if (dev_id and cand.get("device_id") == dev_id) or (ws_id and ws_id != "default" and cand.get("workspace_id") == ws_id):
                                if not any(c.get("job_id") == cand.get("job_id") for c in candidate_jobs):
                                    candidate_jobs.append(cand)
                    except Exception:
                        pass

    if candidate_jobs:
        candidate_jobs.sort(key=lambda x: str(x.get("updated_at", x.get("created_at", ""))), reverse=True)
        return jsonify({"active": True, "job": candidate_jobs[0]})

    # 3. Nếu không có job, kiểm tra video trong workspace của RIÊNG NGƯỜI NÀY
    video_path = os.path.join(ws_dir, "input_video.mp4")
    if not os.path.exists(video_path) or os.path.getsize(video_path) < 100:
        video_path = os.path.join(TEMP_DIR, "input_video.mp4")
    if os.path.exists(video_path) and os.path.getsize(video_path) > 100:
        return jsonify({
            "active": False,
            "has_input_video": True,
            "source_url": f"/workspace/{ws_id}/input_video.mp4",
            "workspace": ws_id
        })

    return jsonify({"active": False, "workspace": ws_id})

@app.route("/api/pipeline/job_video/<job_id>/<filename>")
def api_pipeline_job_video(job_id, filename):
    job_dir = os.path.join(SERVER_JOBS_DIR, job_id)
    if os.path.exists(os.path.join(job_dir, filename)):
        return send_from_directory(job_dir, filename, conditional=True)
    ws_dir = get_workspace_dir(request)
    if os.path.exists(os.path.join(ws_dir, filename)):
        return send_from_directory(ws_dir, filename, conditional=True)
    if os.path.exists(os.path.join(TEMP_DIR, filename)):
        return send_from_directory(TEMP_DIR, filename, conditional=True)
    # Tự động chuyển hướng sang Link trực tiếp hoặc GoFile nếu file chưa về đĩa Railway
    with SERVER_JOBS_LOCK:
        job = ACTIVE_SERVER_JOBS.get(job_id)
    if not job:
        job_file = os.path.join(job_dir, "state.json")
        if os.path.exists(job_file):
            try:
                with open(job_file, "r", encoding="utf-8") as f:
                    job = json.load(f)
            except Exception:
                pass
    if job:
        if job.get("gofile_url"):
            return redirect(job["gofile_url"])
        if job.get("direct_url"):
            return redirect(job["direct_url"])
    return send_from_directory(TEMP_DIR, filename, conditional=True)

