@app.route("/api/admin/login", methods=["POST"])
def api_admin_login():
    data = request.json or {}
    password = data.get("password", "")
    if verify_admin_password(password):
        exp = int(time.time()) + 86400 * 7
        token_payload = f"admin|{exp}"
        sig = hmac.new(SERVER_HMAC_SECRET.encode("utf-8"), token_payload.encode("utf-8"), hashlib.sha256).hexdigest()[:16]
        token = f"{token_payload}|{sig}"
        return jsonify({"status": "ok", "token": token})
    return jsonify({"error": "Mật khẩu quản trị Admin không chính xác!"}), 401

def check_admin_token(req):
    auth = req.headers.get("Authorization", "")
    token = auth.replace("Bearer ", "").strip() if "Bearer " in auth else auth.strip()
    if not token or "|" not in token:
        return False
    parts = token.split("|")
    if len(parts) != 3:
        return False
    role, exp_str, sig = parts
    if role != "admin":
        return False
    try:
        if int(exp_str) < int(time.time()):
            return False
    except ValueError:
        return False
    expected = hmac.new(SERVER_HMAC_SECRET.encode("utf-8"), f"admin|{exp_str}".encode("utf-8"), hashlib.sha256).hexdigest()[:16]
    return sig == expected

